       <div style="position:relative">
         <button class="btn btn-sm" onclick="toggleModelMenu(event)" id="model-btn" style="font-size:12px;padding:6px 10px">
           <span id="model-name">OWL Alpha</span> ▾
         </button>
       </div>
       <span class="access-badge" id="access-mode"></span>
       <a id="web-login-link" class="tunnel-url" style="display:none" target="_blank" rel="noopener">Войти через веб</a>
       <a id="tunnel-link" class="tunnel-badge" style="display:none" target="_blank" rel="noopener">🌐</a>
       <span id="tunnel-url" class="tunnel-url" style="display:none" onclick="copyTunnelUrl()"></span>
     </div>
   </div>

   <!-- DRAWER (sidebar replacement) -->
   <div class="drawer-overlay" id="drawer-overlay" onclick="toggleDrawer()"></div>
