             <span style="flex:1"></span>
             <button class="btn btn-sm" id="snap-reload" onclick="snapLoad(true)">🔄</button>
             <button class="btn btn-p btn-sm" id="snap-restore" onclick="snapRestore()" disabled>♻ Восстановить</button>
           </div>
           <div id="snap-note" style="font-size:12px;color:var(--t2);margin-top:8px">Снапшоты читаются по требованию (work-backup, только дерево — быстро).</div>
           <div id="snap-list" style="margin-top:10px"></div>
           <div id="snap-prog-wrap" style="display:none;margin-top:10px">
             <div style="display:flex;align-items:center;gap:8px">
               <div class="spin" id="snap-spin" style="width:16px;height:16px;border:2px solid var(--bdr);border-top-color:var(--acc);border-radius:50%;animation:snap-rot 1s linear infinite"></div>
               <span id="snap-prog-title" style="font-size:12px;font-weight:600;color:var(--acc)">Восстановление…</span>
               <span style="flex:1"></span>
               <span id="snap-prog-time" style="font-size:12px;color:var(--t3)">0:00</span>
             </div>
             <div id="snap-prog" style="margin-top:8px;max-height:220px;overflow-y:auto;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;padding:8px;font:11px/1.5 monospace;white-space:pre-wrap;word-break:break-word;color:var(--t2)"></div>
           </div>
         </div>
         <style>@keyframes snap-rot{to{transform:rotate(360deg)}} .snap-row{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid var(--bdr);border-radius:10px;margin-bottom:8px;background:var(--bg0);cursor:pointer} .snap-row.sel{border-color:var(--acc);background:var(--bg3)} .snap-row input{position:absolute;opacity:0} </style>
       </div>

       <!-- GIT — local + GitHub repos + builds -->
       <div class="page" id="p-git">
         <div class="ph"><h1>🐙 Git</h1><p>Локальный репозиторий + GitHub: все репозитории, ветки, коммиты, сборки</p></div>
         <div style="display:flex;gap:8px;margin-bottom:12px;align-items:center;flex-wrap:wrap">
           <input type="text" id="git-path" placeholder="путь к локальному репозиторию (с .git)" style="min-width:180px;flex:1;padding:10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:13px;font-family:monospace;outline:none" onkeydown="if(event.key==='Enter')loadGit()">
           <button class="btn btn-p" onclick="loadGit()">⟳</button>
         </div>
         <div id="git-repo" style="font-size:11px;color:var(--t3);margin-bottom:8px"></div>
         <div id="git-status"></div>
         <div style="margin-top:16px;margin-bottom:6px;font-size:12px;color:var(--t2);font-weight:600">Diff</div>
         <pre class="git-pre" id="git-diff"></pre>
         <div style="margin-top:16px;margin-bottom:6px;font-size:12px;color:var(--t2);font-weight:600">Log</div>
         <pre class="git-pre" id="git-log"></pre>

         <!-- GitHub repos -->
         <div id="gh-repos-section" style="margin-top:24px;padding-top:16px;border-top:1px solid var(--bdr)">
           <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap">
             <h2 style="font-size:16px;font-weight:700">GitHub — Репозитории</h2>
             <button class="btn btn-p btn-sm" onclick="ghLoadRepos()">⟳ Обновить</button>
             <span id="gh-repos-count" style="font-size:11px;color:var(--t3)"></span>
           </div>
           <div id="gh-repos-grid" style="display:grid;grid-template-columns:1fr;gap:10px"></div>
         </div>

         <!-- Repo detail -->
         <div id="gh-repo-detail" style="display:none;margin-top:16px;padding-top:16px;border-top:1px solid var(--bdr)">
           <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap">
             <button class="btn btn-sm" onclick="ghBackToList()">← Вернуться к списку</button>
             <h2 id="gh-repo-name" style="font-size:16px;font-weight:700"></h2>
             <span id="gh-repo-desc" style="font-size:12px;color:var(--t2)"></span>
             <div style="position:relative">
               <button class="btn btn-p btn-sm" onclick="toggleGhAgentMenu(event)" title="Клонировать и открыть в любом агенте как в Файлах">📂 Открыть в агенте</button>
