 const DEFAULT_EMULATOR = 'pixel_7_api34';
 const cleanEmulatorName = (value) => {
   const s = String(value || '').trim();
   return /^[A-Za-z0-9._-]{1,80}$/.test(s) ? s : null;
 };
 const getDefaultEmulator = () => {
