   res.json({ home: HOME, workDir: WORK_DIR, platform: process.platform, runId: process.env.GITHUB_RUN_ID || '', runNumber: process.env.GITHUB_RUN_NUMBER || '', ...hubBuildInfo(), ...getAccessInfo(req), state,
