   try {
     const u = new URL(req.url, 'http://localhost');
     const def = Number(process.env.HUB_AUDIO_CHANNELS) || 2;
     return Number(u.searchParams.get('channels') || def) === 1 ? 1 : 2;
   } catch { return 2; }
