 // ─── TUNNEL STATE ───
 // A quick-tunnel URL is ephemeral. Keep its lifecycle separate from the
 // public state so a dead cloudflared process can never leave a clickable URL
 // behind (that stale URL is what produces Cloudflare Error 1033).
 let tunnelInfo = null; // { state, url, type, error, startedAt, retryAt }
 let activeTunnel = null; // { close, onExit, isAlive, healthCheck }
 // How many probes in a row must fail before the connector is thrown away.
 // One probe on a busy runner can time out while the tunnel is perfectly alive,
 // and reopening on the first failure is its own kind of 1033: the panel keeps
 // the old address for the whole window until the new one passes its own check.
 // The shell keeper already uses this rule (MAIN_FAILS >= 3 in
 // tools/tunnel_keeper.sh) - the hub now answers with the same patience.
 const TUNNEL_HEALTH_FAILS = parseInt(process.env.TUNNEL_HEALTH_FAILS || '3', 10) || 3;
 let tunnelRestartTimer = null;
 let tunnelHealthTimer = null;
 let tunnelStopped = false;
 let tunnelFailure = 0;

 function stopManagedTunnel() {
   tunnelStopped = true;
   if (tunnelRestartTimer) clearTimeout(tunnelRestartTimer);
   if (tunnelHealthTimer) clearInterval(tunnelHealthTimer);
   tunnelRestartTimer = null;
   tunnelHealthTimer = null;
   if (activeTunnel && activeTunnel.close) {
     try { activeTunnel.close(); } catch {}
   }
   activeTunnel = null;
 }

 function startManagedTunnel(port, type) {
   tunnelStopped = false;
   tunnelFailure = 0;
   const launch = async () => {
     if (tunnelStopped) return;
     const startedAt = new Date().toISOString();
     tunnelInfo = { state: 'starting', url: null, type, error: null, startedAt, retryAt: null };
     console.log(`  🔗 Starting ${type} tunnel (the URL is withheld until it passes a health check)...`);
     let result;
     try {
       result = await startTunnel(port, type);
     } catch (e) {
       result = { error: e.message };
     }
     if (tunnelStopped) {
       if (result && result.close) result.close();
       return;
     }
     if (!result || !result.url) {
       tunnelFailure += 1;
       const delay = Math.min(30000, 3000 * tunnelFailure);
       const error = (result && result.error) || 'tunnel did not start';
       tunnelInfo = {
         state: 'error', url: null, type, error, startedAt,
         retryAt: new Date(Date.now() + delay).toISOString()
       };
       console.log(`  ❌ Tunnel error: ${error}`);
       console.log(`  🔁 Retrying tunnel in ${Math.ceil(delay / 1000)}s.`);
       tunnelRestartTimer = setTimeout(() => { tunnelRestartTimer = null; launch(); }, delay);
       return;
     }

     tunnelFailure = 0;
     activeTunnel = result;
     tunnelInfo = {
       state: 'ready', url: result.url, type: result.type || type,
       error: null, startedAt, retryAt: null
     };
     console.log(`  🌐 Public:  ${result.url}`);
     console.log(`  📋 Type:    ${result.type || type}`);

     const reconnect = reason => {
       if (tunnelStopped || tunnelRestartTimer) return;
       if (tunnelHealthTimer) clearInterval(tunnelHealthTimer);
       tunnelHealthTimer = null;
       activeTunnel = null;
       const delay = 3000;
       tunnelInfo = {
         state: 'reconnecting', url: null, type: result.type || type,
         error: reason, startedAt, retryAt: new Date(Date.now() + delay).toISOString()
       };
       console.log(`  ⚠ ${reason}; hiding the stale URL and reopening it.`);
       tunnelRestartTimer = setTimeout(() => { tunnelRestartTimer = null; launch(); }, delay);
     };

     // A connector can remain as a process while its edge connection is lost.
     // Process liveness alone is therefore insufficient to prevent Error 1033.
     let healthFails = 0;
     if (typeof result.healthCheck === 'function') {
       tunnelHealthTimer = setInterval(async () => {
         if (tunnelStopped || activeTunnel !== result) return;
         let reason = null;
         try {
           const health = await result.healthCheck();
           if (health && health.ok) { healthFails = 0; return; }
           reason = `HTTP ${health && health.status || 'нет ответа'}`;
         } catch (e) {
           reason = e.message;
         }
         healthFails += 1;
         if (healthFails < TUNNEL_HEALTH_FAILS) {
           console.log(`  ⚠ public tunnel probe ${healthFails}/${TUNNEL_HEALTH_FAILS} failed (${reason}); URL kept until it fails again.`);
           return;
         }
         try { result.close(); } catch {}
         reconnect(`public tunnel health check failed ${healthFails} probes in a row (${reason})`);
       }, 30000);
       tunnelHealthTimer.unref?.();
     }

     if (typeof result.onExit === 'function') {
       result.onExit(info => {
         if (tunnelStopped || info.intentional) return;
         reconnect(`connector exited${info.code == null ? '' : ` (code ${info.code})`}`);
       });
     }
   };
   launch();
 }

 // ─── START ───
 // One attempt at a time: each listen() call stacks its own 'listening'
 // callback on the shared server object, so a failed attempt left its callback
 // attached and the successful retry fired BOTH onReady(oldPort) and
 // onReady(newPort) - measured: double startup banner, and in --tunnel mode
 // that would open two tunnels. Remove the previous attempt's listeners before
 // retrying.
 function tryListen(port, onReady) {
   const ready = () => onReady(port, server);
   const onError = (err) => {
     if (err.code === 'EADDRINUSE') {
       if (process.env.HUB_PORT_STRICT === '1') {
         console.error(`  ❌ Port ${port} is already in use; refusing to start a second hub.`);
         process.exit(1);
       }
       const next = Number(port) + 1;
       console.log(`  ⚠ Port ${port} is busy, trying ${next}...`);
       server.removeListener('listening', ready);
       server.removeListener('error', onError);
       tryListen(next, onReady);
     } else {
       console.error(`  ❌ Server error: ${err.message}`);
       process.exit(1);
     }
   };
   server.once('listening', ready);
   server.on('error', onError);
   server.listen(port, HOST);
 }

 function onReady(actualPort) {
   // Update PORT global for all routes/display
   process.env.PORT = actualPort;

   const nets = os.networkInterfaces();
   const allIPs = [];
   for (const [name, iface] of Object.entries(nets)) {
     for (const cfg of iface) {
       if (cfg.family === 'IPv4' && !cfg.internal) {
         allIPs.push({ name, ip: cfg.address });
       }
     }
   }
   console.log(`\n  ◆ NPM Hub running on port ${actualPort}:`);
   console.log(`    Local:   http://localhost:${actualPort}`);
   if (HOST_ALIAS && hostAliasInstalled) console.log(`    Alias:   http://${HOST_ALIAS}:${actualPort}  (via /etc/hosts, LAN only)`);
   if (allIPs.length > 0) {
     console.log(`    Network:`);
     for (const { name, ip } of allIPs) {
       console.log(`      ${ip}:${actualPort}  (${name})`);
     }
   }

   // Tunnel mode
   const tunnelType = process.argv.find(a => a.startsWith('--tunnel='))?.split('=')[1]
     || (process.argv.includes('--tunnel') ? process.argv[process.argv.indexOf('--tunnel') + 1] : null);

   if (tunnelType) {
     startManagedTunnel(actualPort, tunnelType);
   } else {
     console.log('');
   }

   try { require('child_process').exec(`start http://localhost:${actualPort}`); } catch {}

   // Keep a readable copy of the opencode chat history in ~/.local/share/
   // opencode/history/ (a stable dir outside /tmp, which the OS may clean at
   // any moment) — run once at startup, then daily while the hub lives.
   // PUBLISH=1 + GH_TOKEN pushes a bundle to the session-state branch too.
   const backupHistory = (first) => {
     const { spawn } = require('child_process');
     const script = path.join(__dirname, '..', '..', 'tools', 'backup-chat-history.sh');
     if (!fs.existsSync(script)) return;
     const child = spawn('bash', [script], {
       env: { ...process.env, PUBLISH: '1' },
       stdio: ['ignore', 'ignore', 'pipe']
     });
     child.on('error', () => {});
     if (first) console.log('  💾 Chat-history backup scheduled (daily).');
   };
   backupHistory(true);
   setInterval(() => backupHistory(false), 24 * 60 * 60 * 1000);
 }

 // ─── ALWAYS-ON DESKTOP ───
 // The screen must be there before anyone asks for it: vnc-keepalive starts the
 // Xvfb/openbox/x11vnc/websockify stack on THIS runner, proxies it under
 // /novnc + /ws/desktop, paints the wallpaper/shortcuts and repairs it every
 // 15 s. Started before the listener so the proxy is registered on `server`.
 let vncKeeper = null;
 try {
   vncKeeper = require('./vnc-keepalive').start({
     repoRoot: GIT_ROOT,
     app,
     server,
     port: PORT,
     gate: (req, socket) => gateDenySocket(req, socket),
     log: (m) => console.log('  🖥 ' + m)
   });
   console.log('  🖥 Always-on desktop: ' + JSON.stringify(vncKeeper.status().note));
 } catch (e) {
   console.log('  🖥 vnc-keepalive не запустился: ' + e.message);
 }

 // Best-effort local DNS alias (HOST_ALIAS): must be in place before the first
 // /api/info|networks probes and before onReady decides what to advertise.
 if (HOST_ALIAS) ensureHostAlias().then(() => tryListen(PORT, onReady));
 else tryListen(PORT, onReady);

 // ─── TUNNEL API ───
 app.get('/api/tunnel', (req, res) => {
   if (tunnelInfo && tunnelInfo.state === 'ready' && tunnelInfo.url) {
     res.json({
       success: true,
       status: 'ready',
       url: tunnelInfo.url,
       type: tunnelInfo.type,
       startedAt: tunnelInfo.startedAt
     });
   } else {
     res.json({
       success: false,
       status: (tunnelInfo && tunnelInfo.state) || 'disabled',
       url: null,
       type: (tunnelInfo && tunnelInfo.type) || null,
       error: (tunnelInfo && tunnelInfo.error) || null,
       retryAt: (tunnelInfo && tunnelInfo.retryAt) || null
     });
   }
 });

 // ─── ON-DEMAND WORK-REPO RESTORE (Snapshot tab) ───
 // Boot no longer restores repositories (that cost ~4 minutes before the hub
 // could publish its address): the user picks a snapshot from the Snapshot tab
 // after they are in. Listing uses a tree-only partial clone (objects are just
 // filenames+sizes, so a 100 MB snapshot index costs a few KB); the restore
 // itself goes through the very same tools/restore-work.sh the workflow used.
 const RESTORE_WORK_SH = path.join(__dirname, '..', '..', 'tools', 'restore-work.sh');
 const WB_CACHE_DIR = path.join(DATA_DIR, 'tmp', 'work-backup-index');
 let wbIndex = { sha: '', at: 0, snapshots: [], recommended: '' };
 let wbRestore = { running: false, startedAt: 0, doneAt: 0, code: null, tail: [] };

 const wbRemote = () => {
   const token = runnerToken();
   const repo = process.env.GITHUB_REPOSITORY || '';
   if (!token || !repo) return '';
   return `https://x-access-token:${token}@github.com/${repo}.git`;
 };
 const wbRunCmd = (cmd, args, timeoutMs) => new Promise((resolve) => {
   let out = '', expired = false, child;
   try { child = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] }); }
   catch (e) { return resolve({ code: 1, out: '', err: e.message }); }
   const timer = setTimeout(() => { expired = true; try { child.kill('SIGKILL'); } catch {} }, timeoutMs || 60000);
   child.stdout.on('data', d => { out += String(d); });
   child.stderr.on('data', d => { out += String(d); });
   child.on('error', e => { clearTimeout(timer); resolve({ code: 1, out, err: e.message }); });
   child.on('close', code => { clearTimeout(timer); resolve({ code: expired ? 124 : (code || 0), out: out.slice(0, 400000), err: '' }); });
 });
 const wbPushTail = (s) => {
   for (const ln of String(s).split('\n')) {
     const v = ln.trim();
     if (!v) continue;
     wbRestore.tail.push(v.slice(0, 300));
     if (wbRestore.tail.length > 250) wbRestore.tail.shift();
   }
   // mirror into the hub log for post-mortem
   try { fs.appendFileSync(path.join(LOG_DIR, 'restore-work-manual.log'), String(s)); } catch {}
 };

 app.get('/api/work-snapshots', async (req, res) => {
   try {
     const remote = wbRemote();
     if (!remote) return res.json({ success: true, snapshots: [], recommended: '', note: 'не на Actions-раннере' });
     // ls-remote is the cheap freshness check; refresh the tree only when the
     // branch really moved (a snapshot push) or every 5 minutes max.
     const heads = await wbRunCmd('git', ['ls-remote', remote, 'refs/heads/work-backup'], 30000);
     const sha = (heads.out.trim().split(/\s+/)[0] || '').trim();
     if (!sha || heads.code !== 0 || !/^[0-9a-f]{40}$/.test(sha)) {
       return res.json({ success: true, snapshots: wbIndex.snapshots || [], recommended: wbIndex.recommended || '', note: 'ветка work-backup пока пустая' });
     }
     if (wbIndex.sha !== sha || !wbIndex.at || (Date.now() - wbIndex.at) > 300000) {
       fs.mkdirSync(WB_CACHE_DIR, { recursive: true });
       if (!fs.existsSync(path.join(WB_CACHE_DIR, 'HEAD'))) {
         const init = await wbRunCmd('git', ['init', '-q', '--bare', WB_CACHE_DIR], 20000);
         if (init.code !== 0) throw new Error('git init: ' + init.out.slice(0, 200));
       }
       const fch = await wbRunCmd('git', ['--git-dir=' + WB_CACHE_DIR, 'fetch', '-q', '--depth=1', '--filter=blob:none', remote, '+refs/heads/work-backup:refs/wb'], 180000);
       if (fch.code !== 0) throw new Error('fetch: ' + fch.out.slice(0, 200));
       const tree = await wbRunCmd('git', ['--git-dir=' + WB_CACHE_DIR, 'ls-tree', '-r', '-l', 'refs/wb', '--', 'snapshots/'], 60000);
       if (tree.code !== 0) throw new Error('ls-tree: ' + tree.out.slice(0, 200));
       const snaps = new Map();
       for (const line of tree.out.split('\n')) {
         const m = line.match(/^\S+ blob +\S+ +(\d+)\tsnapshots\/([^/]+)\/(.+)$/);
         if (!m) continue;
         const size = parseInt(m[1], 10) || 0;
         const stamp = m[2], rel = m[3];
         let s = snaps.get(stamp);
         if (!s) { s = { stamp, repos: new Map(), extras: 0, chats: 0, settings: false, total: 0 }; snaps.set(stamp, s); }
         s.total += size;
         const base = rel.split('/').pop();
         const dir = rel.slice(0, -(base.length + 1));
         if (base === 'repo.bundle' || base === 'worktree.tar.gz') {
           const e = s.repos.get(dir) || { rel: dir, bytes: 0, kind: '' };
           if (size > 0) { e.bytes += size; e.kind = base === 'repo.bundle' ? 'git' : 'архив'; }
           s.repos.set(dir, e);
         } else if (base === 'wip.patch' || base === 'untracked.tar.gz') {
           if (size > 0) s.extras += size;
         } else if (rel.startsWith('opencode/chats/') && base.endsWith('.json')) {
           s.chats += 1;
         } else if (rel.startsWith('opencode/settings/') && base !== 'manifest.json') {
           s.settings = true;
         }
       }
       const list = [...snaps.values()].map(s => {
         const active = s.repos.size > 0 || s.chats > 0 || s.settings;
         return {
           stamp: s.stamp,
           repos: [...s.repos.values()].filter(r => r.bytes > 0).sort((a, b) => a.rel.localeCompare(b.rel)),
           extrasMb: Math.round(s.extras / 104857.6) / 10,
           chats: s.chats, settings: s.settings, active,
           totalMb: Math.round(s.total / 104857.6) / 10
         };
       });
       list.sort((a, b) => b.stamp.localeCompare(a.stamp));
       // "Всегда самые новые; если новые пустые — последние, где что-то делали":
       // рекомендация = новейший снапшот с реальной активностью (репо или чаты
       // opencode или настройки), а не просто самый свежий по времени.
       const recommended = (list.find(s => s.active) || { stamp: '' }).stamp;
       wbIndex = { sha, at: Date.now(), snapshots: list, recommended };
     }
     res.json({ success: true, snapshots: wbIndex.snapshots, recommended: wbIndex.recommended });
   } catch (e) {
     res.json({ success: false, error: 'не прочитал work-backup: ' + e.message });
   }
 });

 app.post('/api/work-snapshots/restore', express.json(), (req, res) => {
   try {
     const stamp = String((req.body && req.body.snapshot) || '').trim();
     if (!stamp || !/^[A-Za-z0-9._:-]+$/.test(stamp) || stamp.includes('..') || stamp.includes('/')) {
       return res.json({ success: false, error: 'некорректное имя снапшота' });
     }
     if (wbRestore.running) return res.json({ success: false, error: 'восстановление уже идёт' });
     const token = runnerToken();
     if (!token) return res.json({ success: false, error: 'нет токена GitHub' });
     if (!fs.existsSync(RESTORE_WORK_SH)) return res.json({ success: false, error: 'нет скрипта восстановления' });
     wbRestore = { running: true, startedAt: Date.now(), doneAt: 0, code: null, tail: [] };
     wbPushTail('♻ восстановление из snapshots/' + stamp + '\n');
     const env = Object.assign({}, process.env, {
       GH_TOKEN: token,
       GITHUB_TOKEN: token,
       GITHUB_REPOSITORY: process.env.GITHUB_REPOSITORY || '',
       HUB_LOGS: LOG_DIR,
       WORK_BACKUP_ROOT: HOME,
       WORK_BACKUP_RESTORE_EXISTING: '1',
       WORK_BACKUP_SNAPSHOT: 'snapshots/' + stamp
     });
     const child = spawn('bash', [RESTORE_WORK_SH], { env, stdio: ['ignore', 'pipe', 'pipe'] });
     child.stdout.on('data', d => { process.stdout.write(d); wbPushTail(d); });
     child.stderr.on('data', d => { wbPushTail(d); });
     const timer = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} ; wbPushTail('⏱ таймаут 40 минут — прервал'); }, 40 * 60000);
     child.on('error', e => { clearTimeout(timer); wbRestore.running = false; wbRestore.doneAt = Date.now(); wbRestore.code = -1; wbPushTail('ошибка запуска: ' + e.message); });
     child.on('close', code => { clearTimeout(timer); wbRestore.running = false; wbRestore.doneAt = Date.now(); wbRestore.code = code; wbPushTail(code === 0 ? '✅ восстановление завершено' : ('❌ скрипт завершился с кодом ' + code)); });
     res.json({ success: true });
   } catch (e) {
     res.json({ success: false, error: e.message });
   }
 });

 app.get('/api/work-snapshots/restore/status', (req, res) => {
   const t = wbRestore;
   res.json({
     success: true,
     running: t.running,
     startedAt: t.startedAt || 0,
     doneAt: t.doneAt || 0,
     code: t.code,
     elapsed: t.startedAt ? Math.round((((t.running ? Date.now() : t.doneAt) || Date.now()) - t.startedAt) / 1000) : 0,
     tail: t.tail.slice(-80)
   });
 });

 // ─── PULSE AUDIO AUTO-START ───
 (async () => {
   try {
     const check = await pulseRun('pulseaudio --check 2>&1; echo $?');
     if (!check.out.endsWith('0')) {
       console.log('  🔊 Starting PulseAudio daemon...');
       await pulseRun('pulseaudio --start --disallow-exit --exit-idle-time=-1 2>&1');
       console.log('  🔊 PulseAudio started');
     } else {
       console.log('  🔊 PulseAudio already running');
       await pulseRun('pactl set-exit-idle-time -1 2>/dev/null');
     }
     // Create virtual sinks only when absent: repeated hub restarts must not
     // stack browser_youtube.2/.3 and their old loopbacks.
     let sinkList = await pulseRun('pactl list short sinks 2>/dev/null');
     for (const name of ['cloud_phone', 'browser_youtube']) {
       if (!new RegExp('\\t' + name + '(?:\\.\\d+)?\\t').test(String(sinkList.out || ''))) {
         await pulseRun(`pactl load-module module-null-sink sink_name=${name} sink_properties=device.description="Hub-${name}" 2>/dev/null || true`);
         sinkList = await pulseRun('pactl list short sinks 2>/dev/null');
       }
     }
     // Remove duplicate null-sink modules left by older hub restarts. Pulse
     // silently renames a second sink to browser_youtube.2, so checking only
     // the sink list is not enough; keep the first module for each base name.
     let mods = await pulseRun('pactl list short modules 2>/dev/null');
     const keptNull = new Set();
     for (const line of String(mods.out || '').split('\n')) {
       const m = line.trim().match(/^(\d+)\s+module-null-sink\s+(.+)$/);
       const nm = m && m[2].match(/(?:^|\s)sink_name=(cloud_phone|browser_youtube)(?:\s|$)/);
       if (m && nm) {
         if (keptNull.has(nm[1])) await pulseRun('pactl unload-module ' + m[1] + ' 2>/dev/null || true');
         else keptNull.add(nm[1]);
       }
     }
     // Remove every loopback owned by the previous audio implementation. Its
     // browser_youtube.monitor -> browser_youtube path fed audio back into the
     // same sink, causing hiss/stutter and audio that continued after video end.
     mods = await pulseRun('pactl list short modules 2>/dev/null');
     for (const line of String(mods.out || '').split('\n')) {
       const m = line.trim().match(/^(\d+)\s+module-loopback\s/);
       if (m) await pulseRun('pactl unload-module ' + m[1] + ' 2>/dev/null || true');
     }
     await pulseRun('pactl set-default-sink browser_youtube 2>/dev/null || true');
     // The phone receives browser_youtube.monitor directly; do not loop it back.
     await pulseRun('pactl load-module module-loopback source=cloud_phone.monitor sink=auto_null 2>/dev/null || true');
     console.log('  🔊 Virtual audio sinks ready: cloud_phone, browser_youtube');
   } catch {}
 })();

 const shutdown = () => {
   stopTmuxPollers();
   stopManagedTunnel();
   sessions.forEach(s => { if (s.pty) { try { s.pty.kill(); } catch {} } });
   server.close(() => process.exit(0));
   // server.close waits for long-lived WebSockets. Do not keep a runner alive
   // forever just because a phone disappeared without closing its socket.
   setTimeout(() => process.exit(0), 2000).unref();
 };
 process.on('SIGINT', shutdown);
 process.on('SIGTERM', shutdown);

