                    ?.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                if (launch != null) activity.startActivity(launch)
                else toast("Нечем открыть: $pkg")
            } catch (e: Exception) {
                toast("Не открылось: $pkg")
            }
        }
    }

