app.post('/api/apps', (req, res) => {
  const body = req.body || {};
  if (!Array.isArray(body.apps)) return res.status(400).json({ success: false, error: 'нужен массив apps' });
  const seen = new Set();
  const apps = [];
  for (const a of body.apps.slice(0, APPS_MAX)) {
    const pkg = String((a && a.pkg) || '').trim();
