 // ===== TERMINAL SCROLLBAR (стрелки ▲▼ вместо ползунка) =====
 // Раньше здесь был перетаскиваемый ползунок-слайдер — он не всегда крутил
 // терминал (особенно в alternate screen). Теперь полоса целиком отдана
 // стрелкам ▲▼: по нажатию (и удержанию) они листают терминал в любом режиме —
 // обычном (viewport) и alternate (событиями колеса, как в vim/htop/OpenCode).
 function attachTermScroll(id, panel) {
   const termEl = document.getElementById('term-' + id);
   const vp = termEl.querySelector('.xterm-viewport');
   if (!vp) return null;
   const term = (tabs.find(t => t.id === id) || {}).term;
   const isAlt = () => { const b = term && term.buffer && term.buffer.active; return !!(b && b.type === 'alternate'); };
   const fireWheel = (dy) => {
     if (!term) return;
     const scr = termEl.querySelector('.xterm-screen') || termEl;
     try { scr.dispatchEvent(new WheelEvent('wheel', { deltaY: dy, deltaMode: 0, bubbles: true, cancelable: true, composed: true })); } catch (_) {}
   };
   const upBtn = panel.querySelector('.term-scroll-arr.up');
   const dnBtn = panel.querySelector('.term-scroll-arr.down');
   const track = panel.querySelector('.term-scroll-track');
   // Тусклим стрелку, если в её сторону крутить уже некуда.
   const syncArrows = () => {
     if (!upBtn || !dnBtn) return;
     if (isAlt()) { upBtn.classList.remove('dim'); dnBtn.classList.remove('dim'); return; }
     const max = vp.scrollHeight - vp.clientHeight;
     upBtn.classList.toggle('dim', max <= 0 || vp.scrollTop <= 0);
     dnBtn.classList.toggle('dim', max <= 0 || vp.scrollTop >= max - 1);
   };
   // Стрелки листают как настоящее колесо мыши: шлём WheelEvent прямо в
   // терминал (xterm сам скроллит scrollback на обычном буфере и отдаёт
   // приложению/пейджеру на alternate — меньше, vim, top — ровно как мышь).
   const scrollStep = (dir) => {
     fireWheel(dir === 'up' ? -140 : 140);
   };
   let arrTimer = null;
   const arrStop = () => { if (arrTimer) { clearInterval(arrTimer); arrTimer = null; } };
   const bindArr = (btn, dir) => {
     if (!btn) return;
     btn.addEventListener('pointerdown', (e) => {
       e.preventDefault(); e.stopPropagation();
       btn.classList.add('on'); scrollStep(dir); arrStop();
       arrTimer = setInterval(() => scrollStep(dir), 90);
     });
     ['pointerup', 'pointercancel', 'pointerleave'].forEach(ev => btn.addEventListener(ev, () => { btn.classList.remove('on'); arrStop(); }));
   };
   bindArr(upBtn, 'up');
   bindArr(dnBtn, 'down');
   // ── Плавающие стрелки ──
   // В покое кластер полупрозрачный (чтобы не перекрывать текст), при первом
   // касании/наведении — активный и в фокусе. Ручка ⠿ таскает его куда угодно;
   // тап по ручке возвращает в центр.
   const cluster = panel.querySelector('.term-scroll');
   const handle = cluster && cluster.querySelector('.term-scroll-handle');
   let clusterDrag = false, clusterKeep = null, zoneCleanup = null;
   const clusterActivate = () => { if (!cluster) return; clearTimeout(clusterKeep); cluster.classList.add('chasing'); };
   const clusterArmFade = () => { if (!cluster) return; clearTimeout(clusterKeep); clusterKeep = setTimeout(() => { if (!clusterDrag) cluster.classList.remove('chasing'); }, 1200); };
   if (cluster) {
     cluster.addEventListener('mouseenter', clusterActivate);
     cluster.addEventListener('mouseleave', () => { if (!clusterDrag) clusterArmFade(); });
     cluster.addEventListener('pointerdown', clusterActivate);
     ['pointerup', 'pointercancel'].forEach(ev => cluster.addEventListener(ev, () => { if (!clusterDrag) clusterArmFade(); }));
   }
   if (cluster && handle) {
     const wrap = vp.closest('.term-wrap') || vp.parentElement;
     // Позиция запоминается на устройстве: после перезапуска стрелки снова там,
     // где их поставили (ключ по id терминала — у восстановленных сессий он тот же).
     const TS_LS = 'hub_tscroll_' + id;
     const clusterApply = (x, y) => {
       cluster.style.left = x + 'px'; cluster.style.top = y + 'px'; cluster.style.transform = 'none';
     };
     const clusterReset = () => {
       cluster.style.left = ''; cluster.style.top = ''; cluster.style.transform = '';
       try { localStorage.removeItem(TS_LS); } catch {}
     };
     const clusterClamp = () => {
       const pr = wrap.getBoundingClientRect();
       if (pr.width <= 0 || pr.height <= 0) return;
       const x = parseFloat(cluster.style.left);
       const y = parseFloat(cluster.style.top);
       if (Number.isFinite(x) && Number.isFinite(y)) {
         clusterApply(Math.max(2, Math.min(pr.width - cluster.offsetWidth - 2, x)),
           Math.max(2, Math.min(pr.height - cluster.offsetHeight - 2, y)));
       }
     };
     try {
       const raw = localStorage.getItem(TS_LS);
       if (raw) {
         const p = JSON.parse(raw);
         if (typeof p.x === 'number' && typeof p.y === 'number') clusterApply(p.x, p.y);
       }
     } catch {}
     let clusterDragData = null;
     handle.addEventListener('pointerdown', (e) => {
       e.preventDefault(); e.stopPropagation();
       clusterDrag = true; clusterActivate();
       const r = cluster.getBoundingClientRect();
       clusterDragData = { offX: e.clientX - r.left, offY: e.clientY - r.top, x0: e.clientX, y0: e.clientY };
       try { handle.setPointerCapture(e.pointerId); } catch {}
     });
     handle.addEventListener('pointermove', (e) => {
       if (!clusterDragData) return;
       const pr = wrap.getBoundingClientRect();
       const x = Math.max(2, Math.min(pr.width - cluster.offsetWidth - 2, e.clientX - clusterDragData.offX - pr.left));
       const y = Math.max(2, Math.min(pr.height - cluster.offsetHeight - 2, e.clientY - clusterDragData.offY - pr.top));
       clusterApply(x, y);
     });
     const clusterEndDrag = (e) => {
       if (!clusterDragData) return;
       const moved = Math.abs(e.clientX - clusterDragData.x0) + Math.abs(e.clientY - clusterDragData.y0) > 6;
       clusterDragData = null; clusterDrag = false;
       if (!moved) { clusterReset(); }
       else {
         clusterClamp();
         const x = parseFloat(cluster.style.left);
         const y = parseFloat(cluster.style.top);
         try { localStorage.setItem(TS_LS, JSON.stringify({ x, y })); } catch {}
       }
       clusterArmFade();
     };
     handle.addEventListener('pointerup', clusterEndDrag);
     handle.addEventListener('pointercancel', clusterEndDrag);
     window.addEventListener('resize', clusterClamp);
     zoneCleanup = () => window.removeEventListener('resize', clusterClamp);
   }
   // ── Подушечка виртуальной мыши (как на вкладке «Экран») ──
   // Тянуть по подушечке = крутить колесо (палец вниз → терминал вниз), тап по
   // верхней/нижней половине = шаг. Работает и в alternate (vim/top/OpenCode).
   const pad = cluster && cluster.querySelector('.term-mouse-pad');
   if (pad) {
     let pd = null;
     pad.addEventListener('pointerdown', (e) => {
       e.preventDefault(); e.stopPropagation();
       clusterDrag = true; clusterActivate();
       const r = pad.getBoundingClientRect();
       pd = { y: e.clientY, y0: e.clientY, mid: r.top + r.height / 2, moved: 0 };
       try { pad.setPointerCapture(e.pointerId); } catch {}
     });
     pad.addEventListener('pointermove', (e) => {
       if (!pd) return;
       const dy = e.clientY - pd.y;
       pd.moved += Math.abs(dy);
       pd.y = e.clientY;
       if (Math.abs(dy) >= 3) fireWheel(dy * 7);
       e.preventDefault();
     });
     const padEnd = () => {
       if (!pd) return;
       const wasTap = pd.moved < 6;
       const tapUp = pd.y0 < pd.mid;
       pd = null; clusterDrag = false;
       if (wasTap) scrollStep(tapUp ? 'up' : 'down');
       clusterArmFade();
     };
     pad.addEventListener('pointerup', padEnd);
     pad.addEventListener('pointercancel', padEnd);
   }
   // Тап по пустой середине — листаем на шаг вверх/вниз.
   if (track) track.addEventListener('pointerdown', (e) => {
     e.preventDefault();
     const rect = track.getBoundingClientRect();
     scrollStep(e.clientY > rect.top + rect.height / 2 ? 'down' : 'up');
   });
   vp.addEventListener('scroll', syncArrows);
   let bufSub = null;
   if (term && term.buffer && term.buffer.onBufferChange) { bufSub = term.buffer.onBufferChange(syncArrows); }
   syncArrows();
   return { upd: syncArrows, destroy() { arrStop(); if (bufSub && bufSub.dispose) bufSub.dispose(); vp.removeEventListener('scroll', syncArrows); if (zoneCleanup) zoneCleanup(); } };
 }
 // ── Спасение от «застывшего» агента ──
 // opencode и другие CLI-агенты при исчерпании лимита модели (особенно у
 // бесплатных OpenCode Zen) печатают полноэкранное уведомление/модалку и
 // перестают реагировать на клавиатуру — терминал выглядит «глючным, не даёт
 // нажать что-либо». Даём всегда кликабельный ♻ прямо поверх экрана и, когда
 // сработало НАСТОЯЩЕЕ сообщение о лимите, сами закрываем модалку агента
 // (Esc+Enter), чтобы он снова начал отвечать на клавиатуру.
 let __termRecoverT = null;
 let __termDismissedAt = 0; // throttle: не слать закрытие чаще раза в 10с
 function termRecoverHide() {
   const bar = document.getElementById('term-recover');
   if (bar) bar.classList.remove('on');
   clearTimeout(__termRecoverT);
 }
 function termDismissModal() {
   const t = activeTab;
   if (!t || !t.ws || t.ws.readyState !== 1) return;
   if (Date.now() - __termDismissedAt < 10000) return;
   __termDismissedAt = Date.now();
   // Esc закрывает полноэкранную модалку opencode, Enter гасит промах/промпт.
   for (const k of ['\x1b', '\r']) t.ws.send(JSON.stringify({ type: 'input', data: k }));
 }
 function termRecoverShow(note) {
   const bar = document.getElementById('term-recover');
   if (!bar) return;
   const lbl = document.getElementById('term-recover-note');
   if (lbl) lbl.textContent = note || '♻ Перезапустить сессию';
   bar.classList.add('on');
   clearTimeout(__termRecoverT);
   // Через секунду закрываем саму модалку агента, затем прячем панель — иначе
   // она висит поверх живого терминала.
   setTimeout(termDismissModal, 1200);
   __termRecoverT = setTimeout(termRecoverHide, 8000);
 }
 // ===== ТЕРМИНАЛ НА ПАЛЬЦЕ =====
 // Раньше: ЛЮБОЕ удержание дольше 600 мс копировало текст (а без выделения —
 // последние 200 строк буфера, то есть «весь экран»), а тап дольше 500 мс не
 // возвращал фокус — клавиатура не открывалась. Жалоба: «каждый тап бесконечно
 // копирует весь текст при запуске клавиатуры, когда я хочу печатать».
 // Теперь: тап — печатать (клавиатура), удержание — выделить слово под пальцем,
 // тянуть — расширить выделение по строкам, ⧉ — скопировать.
 function termCellAt(term, x, y) {
   try {
     const screen = term.element && term.element.querySelector('.xterm-screen');
     if (!screen) return null;
     const r = screen.getBoundingClientRect();
     if (!r.width || !r.height) return null;
     const col = Math.floor((x - r.left) / (r.width / term.cols));
     const rowInView = Math.floor((y - r.top) / (r.height / term.rows));
     if (col < 0 || rowInView < 0 || col >= term.cols || rowInView >= term.rows) return null;
     const row = (term.buffer.active.viewportY || 0) + rowInView;
     return { col, row };
   } catch { return null; }
 }

 // Выделяем слово под пальцем; если там пустота — всю непустую строку.
 function termSelectWordAt(term, x, y) {
   const cell = termCellAt(term, x, y);
   if (!cell) return false;
   try {
     const line = term.buffer.active.getLine(cell.row);
     if (!line) return false;
     const text = line.translateToString(true);
     const isWord = (ch) => !!ch && !/\s/.test(ch);
     let s = Math.min(cell.col, Math.max(0, text.length - 1));
     let e = s;
     if (isWord(text[s])) {
       while (s > 0 && isWord(text[s - 1])) s--;
       while (e < text.length - 1 && isWord(text[e + 1])) e++;
     } else {
       const trimmed = text.trim();
       if (!trimmed) return false;
       s = text.indexOf(trimmed);
       e = s + trimmed.length - 1;
     }
     term.select(s, cell.row, e - s + 1);
     return true;
   } catch { return false; }
 }

 function setupTermTouch(termEl, term) {
   if (!isTouch) return null;
   let startY = 0, startX = 0, startT = 0;
   let scrolled = false, selecting = false, anchorRow = 0, holdTimer = null;
   const onStart = (e) => {
     const t = e.touches[0];
     startY = t.clientY; startX = t.clientX; startT = Date.now();
     scrolled = false; selecting = false;
     clearTimeout(holdTimer);
     // Клавиатуру НЕ прячем: тап по терминалу должен её открывать (печатать),
     // а не закрывать.
     holdTimer = setTimeout(() => {
       if (scrolled) return;
       const cell = termCellAt(term, startX, startY);
       if (!cell) return;
       selecting = true;
       anchorRow = cell.row;
       try { if (navigator.vibrate) navigator.vibrate(20); } catch {}
       // Без модалки: просто выделяем слово, как обычный текст на сайте.
       termSelectWordAt(term, startX, startY);
     }, 550);
   };
   const onMove = (e) => {
     const t = e.touches[0];
     if (selecting) {
       // Тянем выделение по строкам.
       const cell = termCellAt(term, t.clientX, t.clientY);
       if (cell && typeof term.selectLines === 'function') {
         try { term.selectLines(Math.min(anchorRow, cell.row), Math.max(anchorRow, cell.row)); } catch {}
       }
       e.preventDefault();
       return;
     }
     if (Math.abs(t.clientY - startY) > 8 || Math.abs(t.clientX - startX) > 8) {
       scrolled = true;
       clearTimeout(holdTimer);
       // Прокрутка с открытой клавиатурой неудобна — прячем её только здесь.
       try { if (term.textarea === document.activeElement) term.blur(); } catch {}
     }
   };
   const onEnd = (e) => {
     clearTimeout(holdTimer);
     if (selecting) {
       selecting = false;
       // Оставляем выделение видимым — копировать можно кнопкой ⧉.
       return;
     }
     if (!scrolled && Date.now() - startT < 550) {
       // Тап = печатать: открываем клавиатуру и снимаем старое выделение.
       try { term.clearSelection(); } catch {}
       term.focus();
     }
   };
   // Долгий тап браузера (контекстное меню) — тоже выделяем, а не копируем молча.
   const onContext = (e) => { e.preventDefault(); termSelectWordAt(term, e.clientX, e.clientY); return false; };
   termEl.addEventListener('touchstart', onStart, { passive: true });
   termEl.addEventListener('touchmove', onMove, { passive: false });
   termEl.addEventListener('touchend', onEnd, { passive: false });
   termEl.addEventListener('contextmenu', onContext);
   return { destroy() { clearTimeout(holdTimer); termEl.removeEventListener('touchstart', onStart); termEl.removeEventListener('touchmove', onMove); termEl.removeEventListener('touchend', onEnd); termEl.removeEventListener('contextmenu', onContext); } };
 }

 async function createTerm(toolId, cwdOverride, plainTerminal, resumeSession) {
   closeModal('modal-newterm');
   const resume = resumeSession && resumeSession.id ? resumeSession : null;
   const effectiveToolId = resume ? (resume.toolId || '_terminal') : toolId;
   const tool = tools.find(t => t.id === effectiveToolId);
   const isPlain = resume ? (!tool || effectiveToolId === '_terminal') : (plainTerminal || toolId === '_terminal' || !tool);

   const id = resume ? String(resume.id) : ('term_' + Date.now());
   const cwdInput = document.getElementById('newterm-cwd')?.value?.trim();
   const cwd = (resume && resume.cwd) || cwdOverride || cwdInput || toolDirs[effectiveToolId] || homeDir;

   if (effectiveToolId && !isPlain) {
     toolDirs[effectiveToolId] = cwd;
     await fetch('/api/last-dir', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ toolId, dir: cwd }) });
   }
   if (!recentPaths.includes(cwd)) {
     recentPaths.unshift(cwd);
     fetch('/api/path-history', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ p: cwd }) });
   }

   const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';

   const term = new Terminal({
