   }
   try {
     const res = await fetch('/api/fs/download?backend=' + fmBackend + '&path=' + encodeURIComponent(p));
     if (!res.ok) return false;
     const blob = await res.blob();
     if (!blob || !blob.size) return false;
     await fsmPutBlob(key, blob);
