 // ЗАЧЕМ. Туннель умирает (1033) или раннер перезапускается — tmux-сессии
 // больше нет, лог тоже (он в TMP_DIR), и терминал открывается чёрным окном:
 // юзер решает, что агент потерян, и начинает заново. Снимок переживает оба
 // случая — он лежит в ~/.npm-hub/sessions, а весь этот каталог едет в
 // work-backup (backup-work.sh → descriptors/) и возвращается на следующем
 // раннере (restore-work.sh, cp -a сохраняет mtime).
 //
 // capture-pane отдаёт плоский текст панели (с цветами благодаря -e), без
 // раскладки по ячейкам: для «показать не чёрный экран, а последнее
 // известное состояние» этого хватает, для пиксельного восстановления TUI —
 // нет. Снимок отдаётся клиенту обычными output-кадрами (см. attachPtyClient),
 // протокол не меняется.
 const SESSION_SNAPSHOT_CAP = parseInt(process.env.SESSION_SNAPSHOT_CAP || String(256 * 1024), 10) || (256 * 1024);
 const SESSION_SNAPSHOT_INTERVAL_MS = parseInt(process.env.SESSION_SNAPSHOT_INTERVAL_MS || '4000', 10) || 4000;
 // Снимок старше суток — это уже не «что было на экране», а мусор из
 // прошлой смены; показывать его вместо пустоты хуже, чем пустота.
 const SESSION_SNAPSHOT_MAX_AGE_MS = parseInt(process.env.SESSION_SNAPSHOT_MAX_AGE_MS || String(24 * 60 * 60 * 1000), 10) || (24 * 60 * 60 * 1000);
 // Свежесозданной сессии снимок не нужен: агент ещё не нарисовал экран, а
 // значит писать пустой файл и коммитить его в work-backup незачем.
 const SESSION_SNAPSHOT_MIN_AGE_MS = 3000;
 // How much of the scrollback is actually re-sent when a client (re)attaches.
 //
 // SESSION_OUTPUT_CAP is what we KEEP, not what we replay. Replaying all 4MB on
 // every reconnect is what made the terminal jump: the frames were appended to a
 // terminal that already had the output, so the view climbed into the middle of
 // the session and the agent's current position scrolled off. It also froze the
 // page - 4MB through term.write() blocks the main thread, which is why every
 // other tab went black for seconds while one tab reconnected.
 //
 // A tail is enough: the terminal has its own scrollback, and what a returning
 // client needs is "where the agent is now", not the whole transcript.
 const SESSION_REPLAY_BYTES = parseInt(process.env.HUB_REPLAY_BYTES || String(512 * 1024), 10) || (512 * 1024);
 const STATE_FILE = path.join(HOME, '.npm-hub-state.json');

