     res.json({ success: true, repo, branch, ahead, behind, lastCommit: lastCommit || null, files, dirty: files.length > 0 });
   } catch (e) { res.json({ success: false, error: e.message }); }
 });

 app.get('/api/git/diff', async (req, res) => {
