Index: app/src/main/assets/panel/index.html
===================================================================
--- app/src/main/assets/panel/index.html	
+++ app/src/main/assets/panel/index.html	
@@ -1,3176 +1,3185 @@
 <!DOCTYPE html>
 <html lang="ru">
 <head>
 <meta charset="utf-8">
 <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
 <meta name="theme-color" content="#0d0d12">
 <link rel="manifest" href="manifest.webmanifest">
 <title>Zen Panel</title>
 <!--
   Single-page control panel for the fork and for the whole GitHub account.

   Everything is inline - no CDN, no external font, no build step - so it works
   from a phone on bad mobile data, inside the APK's WebView, and straight from
   disk. The APK is a thin WebView over this page, so shipping a change here
   updates the app with no reinstall; that is the whole point of loading it from
   the network rather than bundling it.

   It talks to the GitHub REST API from the browser. Reading a public repository
   needs no token, so the page is useful before you paste anything; a token is
   required for private repositories, for starting workflows and for stopping
   sessions. The token is kept in localStorage on the device and is sent only to
   api.github.com.
 -->
 <style>
   :root {
     --bg: #0d0d12; --panel: #16161f; --line: #262633; --raise: #1d1d29;
     --text: #e8e8f0; --dim: #8a8a9e;
     --pink: #ff2d78; --cyan: #22e0d6; --amber: #ffb020; --red: #ff4d4d;
     --green: #3fd17a;
   }
   * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
   body {
     margin: 0; background: var(--bg); color: var(--text);
     font: 15px/1.5 -apple-system, "Segoe UI", Roboto, sans-serif;
     padding: 12px; padding-bottom: 90px;
   }
   h1 { font-size: 21px; margin: 4px 0 2px; letter-spacing: .5px; }
   h1 span { color: var(--pink); }
   .sub { color: var(--dim); font-size: 13px; margin-bottom: 12px; }
   .card {
     background: var(--panel); border: 1px solid var(--line);
     border-radius: 14px; padding: 14px; margin-bottom: 12px;
   }
   .card h2 {
     font-size: 14px; margin: 0 0 10px; color: var(--cyan);
     text-transform: uppercase; letter-spacing: .8px;
   }
   button {
     font: inherit; font-weight: 600; border: 0; border-radius: 10px;
     padding: 11px 13px; margin: 4px 4px 4px 0; cursor: pointer;
     background: var(--pink); color: #fff; min-height: 44px;
   }
   button.ghost { background: transparent; color: var(--cyan); border: 1px solid var(--line); }
   button.small { min-height: 0; padding: 6px 10px; font-size: 12.5px; }
   button:disabled { opacity: .45; }
   input, select {
     font: inherit; width: 100%; padding: 11px; margin: 4px 0 8px;
     background: #0b0b10; color: var(--text);
     border: 1px solid var(--line); border-radius: 10px; min-height: 44px;
   }
   .row { display: flex; gap: 8px; flex-wrap: wrap; }
   .row > * { flex: 1 1 150px; }
   /* The rarely pressed controls live in here: one line instead of six, and
      nothing is lost - tap the summary and they are all still there. */
   details.more { margin-top: 8px; }
   details.more > summary {
     color: var(--dim); font-size: 12.5px; font-weight: 600;
     padding: 8px 0; cursor: pointer; list-style: none;
   }
   details.more > summary::-webkit-details-marker { display: none; }
   details.more > summary::before { content: '▸ '; }
   details.more[open] > summary::before { content: '▾ '; }
   details.more[open] > summary { color: var(--cyan); }
   table { width: 100%; border-collapse: collapse; font-size: 13px; }
   td { padding: 8px 4px; border-bottom: 1px solid var(--line); vertical-align: top; }
   td:first-child { color: var(--dim); white-space: nowrap; width: 1%; padding-right: 12px; }
   .pill {
     display: inline-block; padding: 2px 9px; border-radius: 99px;
     font-size: 12px; font-weight: 700;
   }
   .ok { background: rgba(63,209,122,.15); color: var(--green); }
   .run { background: rgba(255,176,32,.15); color: var(--amber); }
   .bad { background: rgba(255,77,77,.15); color: var(--red); }
   .idle { background: #22222e; color: var(--dim); }
   code, .mono {
     font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
     font-size: 12.5px; word-break: break-all;
   }
   .note { color: var(--dim); font-size: 12.5px; margin-top: 8px; }
   .warn {
     border-left: 3px solid var(--amber); padding-left: 10px;
     color: #ffd79a; font-size: 13px; margin: 10px 0;
   }
   .danger {
     border-left: 3px solid var(--red); padding-left: 10px;
     color: #ffb3b3; font-size: 13px; margin: 10px 0;
   }
   a { color: var(--cyan); }
   .tabs {
     position: fixed; left: 0; right: 0; bottom: 0; display: flex;
     background: #101018; border-top: 1px solid var(--line);
     padding: 6px 4px calc(6px + env(safe-area-inset-bottom)); z-index: 20;
     overflow-x: auto;
   }
   .tabs button {
     flex: 1 0 auto; min-width: 52px; white-space: nowrap;
     background: transparent; color: var(--dim); margin: 0;
     font-size: 11.5px; font-weight: 600; padding: 6px 2px; min-height: 44px;
     border-radius: 8px; line-height: 1.25;
   }
   .tabs button.on { color: var(--pink); background: #191922; }
   .tabs button b { display: block; font-size: 16px; font-weight: 500; }
   .page { display: none; }
   .page.on { display: block; }
   .item {
     display: flex; align-items: center; gap: 10px; padding: 10px 8px;
     border-bottom: 1px solid var(--line); cursor: pointer;
   }
   .item:last-child { border-bottom: 0; }
   .item .ico { width: 20px; text-align: center; color: var(--dim); flex: 0 0 20px; }
   /* Launcher icons get their own column: 20px is for a glyph, not for a real
      app icon. */
   .item .appico {
     width: 34px; height: 34px; flex: 0 0 34px;
     border-radius: 8px; object-fit: cover; background: #1d1d29;
   }
   .item .grow { flex: 1; min-width: 0; }
   .item .name { font-size: 13.5px; word-break: break-word; }
   .item .meta { color: var(--dim); font-size: 11.5px; }
   .crumb { color: var(--dim); font-size: 12.5px; margin-bottom: 8px; word-break: break-all; }
   .crumb a { cursor: pointer; }
   pre {
     background: #0b0b10; border: 1px solid var(--line); border-radius: 10px;
     padding: 10px; overflow: auto; max-height: 60vh; font-size: 12px;
     white-space: pre; -webkit-overflow-scrolling: touch;
   }
   .kv { display: flex; gap: 8px; align-items: center; margin: 6px 0; }
   .kv .k { color: var(--dim); font-size: 12px; width: 84px; flex: 0 0 84px; }
   .kv .v { flex: 1; font-family: ui-monospace, Menlo, Consolas, monospace;
            font-size: 12.5px; word-break: break-all; }
   .avatar { width: 46px; height: 46px; border-radius: 50%; background: #22222e; }
   .head { display: flex; gap: 12px; align-items: center; }
   .spin { color: var(--dim); font-size: 12.5px; }
   #boot-log {
     max-height: 240px; overflow: auto; -webkit-overflow-scrolling: touch;
     font: 12.5px/1.45 ui-monospace, "SF Mono", Menlo, Consolas, monospace;
     background: #0b0b10; border: 1px solid var(--line); border-radius: 10px;
     padding: 8px 10px;
   }
   #boot-log .boot-line { color: var(--text); }
   #boot-log .t { color: var(--dim); margin-right: 8px; }
   .desk-ph {
     height: 110px; display: flex; align-items: center; justify-content: center;
     background: #111118; color: var(--dim); border-radius: 8px; font-size: 12.5px;
     border: 1px dashed var(--line);
   }
   #ready-bar { border-left: 3px solid var(--cyan); }
 </style>
 </head>
 <body>

 <h1>Zen <span>Panel</span></h1>
 <div class="sub" id="subtitle">панель управления</div>

 <!-- ══ ACCOUNT ══════════════════════════════════════════════════════ -->
 <div class="page" id="p-acc">
   <div class="card">
     <h2>Аккаунт</h2>
     <div id="acc"><span class="spin">загрузка…</span></div>
   </div>

   <div class="card">
     <h2>Добавить аккаунт</h2>
     <label>Токен GitHub</label>
     <input id="tok" type="password" placeholder="github_pat_… или ghp_…"
       autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false"
       data-lpignore="true" data-1p-ignore="true" inputmode="text">
     <div class="row">
       <button class="ghost" type="button" onclick="pasteToken()">Вставить из буфера</button>
       <button id="btn-add" onclick="addAccount()">Добавить</button>
       <button class="ghost" onclick="openExternal('https://github.com/settings/tokens/new?scopes=repo,workflow&description=Symbiosis%20panel')">Создать токен</button>
     </div>
     <div class="note">
       Аккаунтов может быть несколько — переключайтесь кнопкой выше. Токен
       хранится только в этом браузере (localStorage) и уходит исключительно на
       api.github.com. Нужны права <code>repo</code> и <code>workflow</code>.
       Без токена видны только публичные репозитории и статусы.
     </div>
   </div>
 </div>

 <!-- ══ REPOS / FILES ════════════════════════════════════════════════ -->
 <div class="page" id="p-repo">
   <div class="card">
     <h2>Репозитории <button class="ghost small" style="float:right"
         onclick="loadRepos(true)">Обновить</button></h2>
     <input id="repo-filter" placeholder="фильтр по имени" oninput="renderRepos()">
     <div class="note" style="margin-top:0">
       🔒 приватный · 🌐 публичный — нажатие на значок меняет видимость.
     </div>
     <div id="repos"><span class="spin">загрузка…</span></div>
   </div>
 </div>

 <!-- ══ FILES (drill-in) ═════════════════════════════════════════════ -->
 <div class="page" id="p-files">
   <div class="card">
     <h2 id="files-title">Файлы</h2>
     <div class="crumb" id="crumb"></div>
     <div id="files"><span class="spin">загрузка…</span></div>
   </div>
 </div>

 <!-- ══ ACTIONS ══════════════════════════════════════════════════════ -->
 <div class="page" id="p-act">
   <div class="card" id="watch-card" style="display:none">
     <h2>Идёт сейчас <button class="ghost small" style="float:right"
         onclick="toggleWatch()" id="watch-btn">пауза</button></h2>
     <div id="watch"></div>
   </div>

   <div class="card">
     <h2>Workflow <button class="ghost small" style="float:right"
         onclick="loadActions(true)">Обновить</button></h2>
     <div class="note" style="margin-top:0">Репозиторий: <code id="act-repo"></code>
       · <a onclick="go('repo')">сменить</a></div>
     <div id="workflows"><span class="spin">загрузка…</span></div>
   </div>
   <div class="card">
     <h2>Последние запуски</h2>
     <div id="runs"><span class="spin">загрузка…</span></div>
   </div>
 </div>

 <!-- ══ SESSIONS ═════════════════════════════════════════════════════ -->
 <div class="page" id="p-sess">
   <div class="card">
     <h2>Столы</h2>
     <div class="note" style="margin-top:0">
       Стол Windows в браузере, без пароля. Живёт до шести часов.
     </div>
     <div class="row" style="margin-top:10px">
       <button id="btn-windows" onclick="launchDesks()">Стол Windows</button>
     </div>
     <input id="first-cmd" placeholder="Первая команда — уйдёт в чат сразу после запуска"
            autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false">
     <div class="row" style="margin-top:8px">
       <button class="ghost small" id="btn-agent" onclick="launchAgent()">CLI-агент</button>
       <button class="ghost small" id="btn-opencode" onclick="launchOpencode()">OpenCode</button>
       <button class="ghost small" id="btn-hub" onclick="launchHub()">NPM-Hub</button>
     </div>
     <div class="note">
       Linux — XFCE и терминал. Windows — собственный рабочий стол раннера.
       CLI-агент, OpenCode и NPM-Hub поднимаются в раннере (Linux или Windows)
       и открываются здесь же, в оверлее. Первая команда, если её указать,
       отправится в чат автоматически.
     </div>
     <div id="agent-conflict" class="warn" style="display:none"></div>
   </div>

   <div class="card" id="boot-card" style="display:none">
     <h2>Подключение</h2>
     <div id="boot-log"></div>
   </div>

   <div class="card" id="ready-bar" style="display:none">
     <h2 id="ready-title">Готово</h2>
     <div class="note" id="ready-sub" style="margin-top:0"></div>
     <div class="row" style="margin-top:8px">
       <button id="ready-open" onclick="openReadyChat()">Открыть чат</button>
       <button class="ghost" onclick="document.getElementById('ready-bar').style.display='none'">Скрыть</button>
     </div>
   </div>

   <div class="card" id="runner-card-panel">
     <h2>Раннер / файлы</h2>
     <div class="note" id="runner-line" style="margin-top:0">Живой хаб не найден — файлы пакаются там же, в хабе.</div>
     <div class="row" style="margin-top:8px">
       <button class="ghost small" id="pr-save" onclick="runnerPanelSave()" disabled>💾 Сохранить</button>
       <button class="ghost small" id="pr-stop" onclick="runnerPanelStop()" disabled>⏻ Выключить</button>
     </div>
     <div id="runner-scan" style="margin-top:8px"></div>
     <div id="runner-res"></div>
   </div>

   <div class="card" id="handoff-card">
     <h2>🔁 Эстафета сессии</h2>
     <div class="note" style="margin-top:0" id="ho-line">читаю настройки…</div>
     <div class="row" style="margin-top:8px">
       <button class="ghost small" id="ho-start" onclick="handoffPanelStart()">🔁 Передать сейчас</button>
       <button class="ghost small" id="ho-continue" onclick="handoffPanelContinue()">▶️ Продолжить</button>
     </div>
     <details class="more" id="ho-more">
       <summary id="ho-more-sum">⚙️ Автопередача и лимиты</summary>
       <div class="row" style="margin-top:8px;gap:10px;flex-wrap:wrap">
         <label class="note" style="display:flex;align-items:center;gap:6px">
           <input id="ho-auto" type="checkbox"> автопередача</label>
         <label class="note">работает до
           <input id="ho-age" type="number" min="0" max="720" step="10" inputmode="numeric"
                  style="width:66px;padding:6px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)"> мин</label>
         <label class="note">простой
           <input id="ho-idle" type="number" min="0" max="720" step="5" inputmode="numeric"
                  style="width:66px;padding:6px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)"> мин</label>
         <label class="note">отсчёт
           <input id="ho-count" type="number" min="30" max="1800" step="30" inputmode="numeric"
                  style="width:66px;padding:6px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)"> с</label>
         <button class="small" onclick="handoffPanelSave()">💾 Сохранить</button>
       </div>
 <div class="note" id="ho-hint" style="margin-top:6px">
       Без «автопередачи» ничего не запускается само: раннер живёт, пока жив GitHub, и уходит только по кнопке.
       С галочкой сессия, которой вы реально пользуетесь, заранее переезжает на новый раннер, чтобы не попасть под 6-часовой лимит.
       Простой — это окно «никто не работает»: внутри него передача разрешена, снаружи раннер просто умрёт от лимита.
       Лимиты хранятся в control-репозитории, поэтому новый раннер читает их сам.
       Передача сначала сохраняет всё на GitHub, потом считает 3 минуты; «Продолжить» отменяет.
       0 = выключено. Если не удалось сохранить — раннер не выключается.
     </div>
     </details>
   </div>

   <div class="card">
     <h2>Активная сессия</h2>
     <div id="live"><span class="spin">проверяю…</span></div>
     <div class="row" style="margin-top:8px">
       <button class="ghost small" onclick="window.open('desks.html','_blank')">
         Столы на отдельной странице</button>
     </div>
   </div>

   <div class="card" id="journal-card">
     <h2>Журнал запусков</h2>
     <div class="note" style="margin-top:0">
       Сгруппирован по дням и дням недели: сколько запусков прошло успешно, сколько
       с ошибкой. Та же запись лежит на ветке <code>session-state</code> в
       <code>history/&lt;дата&gt;/&lt;день&gt;/run-N.json</code> — она не исчезает,
       когда GitHub удаляет старые запуски.
     </div>
     <div id="journal"><span class="spin">читаю…</span></div>
   </div>

   <div class="card" id="desks-card" style="display:none">
     <h2>Столы</h2>
     <div id="desks"></div>
     <div class="note">
       Пароля нет ни у одного: ссылка открывает стол сразу. Кто знает адрес —
       тот управляет; адрес живёт до конца сессии, не дольше шести часов.
     </div>
   </div>

   <div class="card" id="screen-card" style="display:none">
     <h2>Экран</h2>
     <div id="preview"><span class="spin">проверяю…</span></div>
   </div>

   <div class="card" id="creds-card" style="display:none">
     <h2>Доступы</h2>
     <div id="creds"></div>
     <div class="note">
       Публикуются самой сессией и стираются, когда она заканчивается.
     </div>
   </div>
 </div>

 <!-- ══ APK ══════════════════════════════════════════════════════════ -->
 <div class="page" id="p-apk">
   <div class="card">
     <h2>Панель как приложение</h2>
     <div id="apk-panel"><span class="spin">загрузка…</span></div>
     <div class="note">
       Каждый успешный билд публикует GitHub Release: тег <code>v1.N</code> для APK
       и <code>desktop-v1.N</code> для ПК-версии, versionCode = число коммитов.
       Установка поверх старой работает.
     </div>
     <div class="row" style="margin-top:10px">
       <button onclick="run('panel-apk.yml',{})">Собрать и выпустить APK</button>
     </div>
   </div>

   <div class="card">
     <h2>Последний APK эмулятора</h2>
     <div id="apk"><span class="spin">загрузка…</span></div>
     <div class="row" style="margin-top:10px">
       <button onclick="run('build.yml',{upload_to_gofile:'true'})">Собрать APK</button>
       <button class="ghost" onclick="run('tests.yml',{})">Тесты</button>
     </div>
   </div>
 </div>

 <div class="page" id="p-apps">
   <div class="card">
     <h2>Приложения телефона</h2>
     <input id="apps-q" placeholder="поиск" autocomplete="off" oninput="appsRender()">
     <div id="apps-list"><span class="spin">смотрю установки …</span></div>
     <div class="note">
       Это лаунчер: список того, что установлено на телефоне — апп запускается как обычное, живёт сам на телефоне, не в раннере и не по ресурсу его.
       Панель при этом держит связь с хабом и спит в увенном режиме — возвращаясь к активной сессии.
     </div>
   </div>
 </div>

 <div class="tabs">
   <button id="t-acc"  onclick="go('acc')"><b>◉</b>Аккаунт</button>
   <button id="t-repo" onclick="go('repo')"><b>▤</b>Репо</button>
   <button id="t-act"  onclick="go('act')"><b>▶</b>Actions</button>
   <button id="t-sess" onclick="go('sess')"><b>⬢</b>Сессии</button>
   <button id="t-apps" onclick="go('apps')"><b>▦</b>Прилож.</button>
   <button id="t-apk"  onclick="go('apk')"><b>⬇</b>APK</button>
 </div>

 <script>
 'use strict';

 const GH = 'https://api.github.com';

 // ── OFFLINE-LAYER-BEGIN ─────────────────────────────────────────────
 // Панель лежит в APK и открывается всегда, а данные приходят из
 // api.github.com и с хаба. Без сети они падают, и все вкладки показали бы
 // пустоту. Слой подменяет window.fetch: каждый удачный GET (json/text)
 // сохраняется в localStorage, а при обрыве отдаётся последний ответ — с
 // пометкой «офлайн» в баннере. POST/PUT не кешируются и не повторяются.
 (function () {
   'use strict';
   var PREFIX = 'panelcache:';
   var MAX_ENTRIES = 250;
   var offline = false, lastSaved = 0, listeners = [];

   function keys() {
     var out = [];
     try { for (var i = 0; i < localStorage.length; i++) { var k = localStorage.key(i); if (k && k.indexOf(PREFIX) === 0) out.push(k); } } catch (e) {}
     return out;
   }
   function safeSet(k, v) { try { localStorage.setItem(k, v); return true; } catch (e) { prune(); try { localStorage.setItem(k, v); return true; } catch (e2) { return false; } } }
   function safeGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
   function safeRemove(k) { try { localStorage.removeItem(k); } catch (e) {} }
   function prune() {
     var ks = keys().map(function (k) { var t = 0; try { t = JSON.parse(safeGet(k)).t || 0; } catch (e) {} return { k: k, t: t }; });
     ks.sort(function (a, b) { return a.t - b.t; });
     var drop = Math.max(0, ks.length - MAX_ENTRIES);
     for (var i = 0; i < drop; i++) safeRemove(ks[i].k);
   }
   function store(e) {
     if (!e || typeof e.body !== 'string' || e.body.length > 800000) return;
     e.t = Date.now(); lastSaved = e.t;
     safeSet(PREFIX + e.key, JSON.stringify(e));
   }
   function load(key) { var raw = safeGet(PREFIX + key); if (!raw) return null; try { return JSON.parse(raw); } catch (e) { return null; } }
   function hhmm(t) { try { return new Date(t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); } catch (e) { return ''; } }

   // ── Очередь изменяющих действий ──
   // «Отправить в ветку» может не уйти из-за обрыва. Такое действие кладётся
   // сюда и повторяется при связи; x-hub-idem не даёт выполнить его дважды.
   var QKEY = 'panelqueue';
   function qLoad() { try { var v = JSON.parse(safeGet(QKEY) || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; } }
   function qSave(q) { safeSet(QKEY, JSON.stringify(q)); render(); }
   function qAdd(item) { var q = qLoad().filter(function (x) { return x.key !== item.key; }); q.push(item); qSave(q); }
   function qRemove(key) { qSave(qLoad().filter(function (x) { return x.key !== key; })); }
   function idemKey(method, url, body) {
     var s = method + ' ' + url + ' ' + body, h = 5381, i;
     for (i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
     return 'k' + h.toString(16) + '-' + s.length;
   }

   var bar = null;
   function banner() {
     if (bar || !document.body) return bar;
     bar = document.createElement('div');
     bar.style.cssText = 'position:fixed;left:0;right:0;top:0;z-index:2147483647;display:none;align-items:center;gap:8px;justify-content:center;padding:6px 10px;font:600 12px/1.3 system-ui,sans-serif;background:#7a5200;color:#ffe7ad;box-shadow:0 1px 6px rgba(0,0,0,.4)';
     bar.innerHTML = '<span id="panel-offline-text"></span><button id="panel-offline-retry" style="background:#ffe7ad;color:#4a3200;border:0;border-radius:6px;padding:3px 9px;font:600 12px system-ui;cursor:pointer">Повторить</button>';
     document.body.appendChild(bar);
     var r = document.getElementById('panel-offline-retry');
     if (r) r.onclick = function () { location.reload(); };
     return bar;
   }
   function render() {
     if (!banner()) return;
     var n = qLoad().length;
     if (offline || n) {
       var el = document.getElementById('panel-offline-text');
       var txt = offline
         ? ('Офлайн — данные из кеша' + (lastSaved ? ' (' + hhmm(lastSaved) + ')' : ''))
         : 'Есть связь';
       if (n) txt += ' · в очереди: ' + n;
       if (el) el.textContent = (offline ? '⚡ ' : '⏳ ') + txt;
       bar.style.display = 'flex';
     } else { bar.style.display = 'none'; }
   }
   function setOffline(v) {
     if (offline === v) return;
     offline = v; render();
     for (var i = 0; i < listeners.length; i++) { try { listeners[i](offline); } catch (e) {} }
   }

   var realFetch = (typeof window.fetch === 'function') ? window.fetch.bind(window) : null;
   function cacheable(req) {
     if (!realFetch) return null;
     var method = (req.method || 'GET').toUpperCase();
     if (method !== 'GET') return null;
     var url; try { url = new URL(req.url, location.href); } catch (e) { return null; }
     if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
     if (/token|secret|password|passwd|auth/i.test(url.pathname + url.search)) return null;
     return url;
   }
   function isConnectivityUrl(url) {
     try {
       url = url instanceof URL ? url : new URL(url, location.href);
       return url.origin === 'https://api.github.com' || url.origin === location.origin;
     } catch (e) { return false; }
   }
   if (realFetch) {
     window.fetch = function (input, init) {
       var req;
       try { req = (typeof input === 'string' || (input && input.url)) ? new Request(input, init) : input; }
       catch (e) { return realFetch(input, init); }
       var url = cacheable(req);
       if (!url) return realFetch(input, init);
       var key = url.href;
       return realFetch(input, init).then(function (res) {
         if (res && res.ok) {
           if (isConnectivityUrl(url)) setOffline(false);
           var ct = res.headers.get('content-type') || 'application/json';
           if (/(json|text|javascript)/i.test(ct)) {
             try { res.clone().text().then(function (body) { store({ key: key, status: res.status, ct: ct, body: body }); }).catch(function () {}); } catch (e) {}
           }
         }
         return res;
       }).catch(function (err) {
         var c = load(key);
         if (c) {
           if (isConnectivityUrl(url)) setOffline(true);
           return new Response(c.body, { status: c.status || 200, headers: { 'content-type': c.ct || 'application/json', 'x-panel-offline': '1' } });
         }
         if (isConnectivityUrl(url)) setOffline(true);
         throw err;
       });
     };
   }

   // ── Отправка очереди ──
   var flushing = false;
   function flushQueue() {
     if (flushing) return Promise.resolve();
     var q = qLoad();
     if (!q.length) return Promise.resolve();
     flushing = true;
     return (function next(i) {
       if (i >= q.length) { flushing = false; render(); return; }
       var it = q[i];
       return realFetch(it.url, {
         method: it.method,
         headers: Object.assign({ 'content-type': 'application/json', 'x-hub-idem': it.key }, it.headers || {}),
         body: it.body
       }).then(function (r) {
         if (r && r.status >= 200 && r.status < 300) { qRemove(it.key); return next(i + 1); }
         if (r && r.status >= 400 && r.status < 500) { qRemove(it.key); return next(i + 1); }
         flushing = false; render();
       }).catch(function () { flushing = false; render(); });
     })(0);
   }

   window.addEventListener('online', function () { setOffline(false); flushQueue(); });
   window.addEventListener('offline', function () { setOffline(true); });
   if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { render(); flushQueue(); });
   else { render(); flushQueue(); }
   if (!navigator.onLine) setOffline(true);
   if (typeof setInterval === 'function') setInterval(function () { if (qLoad().length) flushQueue(); }, 30000);

   window.PanelOffline = {
     get isOffline() { return offline; },
     get lastSaved() { return lastSaved; },
     save: function (key, obj) { store({ key: key, status: 200, ct: 'application/json', body: JSON.stringify(obj) }); },
     load: load,
     remove: function (key) { safeRemove(PREFIX + key); },
     clear: function () { keys().forEach(safeRemove); },
     on: function (cb) { if (typeof cb === 'function') listeners.push(cb); },
     // «Отправить в ветку»: уходит сразу, а без связи — в очередь и повторится.
     post: function (url, body, label) {
       var bodyStr = (typeof body === 'string') ? body : JSON.stringify(body || {});
       var it = { key: idemKey('POST', url, bodyStr), method: 'POST', url: url, headers: {}, body: bodyStr, label: label || url, ts: Date.now() };
       return realFetch(url, { method: 'POST', headers: { 'content-type': 'application/json', 'x-hub-idem': it.key }, body: it.body })
         .then(function (r) { setOffline(false); return r.json().catch(function () { return { success: r.ok }; }); })
         .catch(function () { qAdd(it); setOffline(true); return { success: true, queued: true, offline: true }; });
     },
     pending: function () { return qLoad(); },
     flush: flushQueue
   };
 })();
 // ── OFFLINE-LAYER-END ───────────────────────────────────────────────

 // Where the panel points when nobody has signed in yet. Any account can be
 // added later; this is only the read-only starting view.
 const DEFAULT_OWNER = 'sj0404-collab';
 const DEFAULT_REPO  = DEFAULT_OWNER + '/zen-panel';

 // No hardcoded tunnel address. The reserved domain is only used when the
 // session actually got it; whichever address a session reports is the one the
 // panel opens. Assuming the static domain is what showed a blank page when
 // something else already held it.

 // ── accounts ────────────────────────────────────────────────────────
 //
 // Several GitHub accounts can be kept side by side and switched between. Each
 // carries its own token and its own control repository - the fork whose
 // workflows this panel starts - because a second account will not have the
 // first one's fork, and firing a workflow into the wrong repository is the
 // mistake worth designing out.
 //
 // Tokens sit in localStorage, on the device, and are sent only to
 // api.github.com. Switching accounts is a local operation: nothing is revoked
 // and nothing is uploaded.
 const STORE_KEY = 'panel_accounts';

 function loadStore() {
   let s = null;
   try { s = JSON.parse(localStorage.getItem(STORE_KEY) || 'null'); } catch (e) { s = null; }
   if (!s || !Array.isArray(s.accounts)) s = { v: 1, active: 0, accounts: [] };

   // Carry over the single token the panel used before accounts existed, so an
   // upgrade does not silently log the user out.
   const legacy = localStorage.getItem('gh_token');
   if (legacy && !s.accounts.some(a => a.token === legacy)) {
     s.accounts.push({ login: '', token: legacy, avatar: '', control: DEFAULT_REPO });
     s.active = s.accounts.length - 1;
     localStorage.removeItem('gh_token');
     try { localStorage.setItem(STORE_KEY, JSON.stringify(s)); } catch (e) {}
   }
   // Workflows now live in zen-panel, not the old Symbiosis fork. A stored
   // control repo pointing at /symbiosis would dispatch into a repo that has
   // no agent.yml / opencode.yml.
   let migrated = false;
   for (const a of s.accounts) {
     if (a.control && /\/(symbiosis|SymbEK)$/i.test(a.control)) {
       a.control = a.login ? (a.login + '/zen-panel') : DEFAULT_REPO;
       migrated = true;
     }
   }
   if (migrated) {
     try { localStorage.setItem(STORE_KEY, JSON.stringify(s)); } catch (e) {}
   }
   if (s.active >= s.accounts.length) s.active = Math.max(0, s.accounts.length - 1);
   return s;
 }

 function saveStore(s) {
   try { localStorage.setItem(STORE_KEY, JSON.stringify(s)); } catch (e) {}
 }

 let STORE = loadStore();

 const acct   = () => STORE.accounts[STORE.active] || null;
 const tok    = () => (acct() && acct().token) || '';
 const owner  = () => (acct() && acct().login) || DEFAULT_OWNER;
 const ctlRepo = () => (acct() && acct().control) || DEFAULT_REPO;

 // The control repository is chosen per account, so this cannot be a constant.
 const CTL = () => `${GH}/repos/${ctlRepo()}`;

 const $ = id => document.getElementById(id);
 const esc = s => String(s == null ? '' : s)
   .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

 function hdr() {
   const h = { 'Accept': 'application/vnd.github+json' };
   if (tok()) h['Authorization'] = 'token ' + tok();
   return h;
 }

 // Adding an account verifies the token before storing it. A token that is
 // expired or missing a scope otherwise turns into an empty panel with no
 // explanation, which is the failure this avoids.
 async function pasteToken() {
   const field = $('tok');
   try {
     if (!navigator.clipboard || !navigator.clipboard.readText) throw new Error('Clipboard API недоступен');
     const value = (await navigator.clipboard.readText()).trim();
     if (!value) throw new Error('Буфер обмена пуст');
     field.value = value;
     field.focus();
   } catch (e) {
     // Some Android WebViews deny clipboard reads. Keep the message actionable.
     alert('Не удалось прочитать буфер: ' + e.message + '. Откройте буфер клавиатуры и выберите скопированный token.');
   }
 }

 async function addAccount() {
   const value = $('tok').value.trim();
   if (!value) { alert('Вставьте токен.'); return; }
   const btn = $('btn-add'); const label = btn.textContent;
   btn.disabled = true; btn.textContent = 'Проверяю…';
   try {
     const r = await fetch(`${GH}/user`, {
       headers: { 'Accept': 'application/vnd.github+json', 'Authorization': 'token ' + value }
     });
     if (r.status === 401) throw new Error('Токен недействителен (401).');
     if (!r.ok) throw new Error('GitHub ответил ' + r.status);
     const u = await r.json();
     const scopes = r.headers.get('x-oauth-scopes') || '';

     const existing = STORE.accounts.findIndex(a => a.login === u.login);
     const entry = {
       login: u.login,
       token: value,
       avatar: u.avatar_url || '',
       scopes,
       // Default the control repository to this account's own fork if it has
       // one; otherwise leave the shared default, which is still readable.
       control: await guessControl(u.login, value)
     };
     if (existing >= 0) { STORE.accounts[existing] = entry; STORE.active = existing; }
     else { STORE.accounts.push(entry); STORE.active = STORE.accounts.length - 1; }
     saveStore(STORE);
     $('tok').value = '';

     if (!/repo/.test(scopes) || !/workflow/.test(scopes)) {
       alert('Аккаунт ' + u.login + ' добавлен, но у токена нет прав repo/workflow — ' +
             'запуск и остановка сессий работать не будут.');
     }
     switchTo(STORE.active);
   } catch (e) {
     alert('Не вышло: ' + e.message);
   } finally {
     btn.disabled = false; btn.textContent = label;
   }
 }

 // Which repository holds the workflows this panel drives. A fork keeps the
 // upstream name, so looking for it by name is right far more often than not;
 // when it is missing the user picks one by hand.
 async function guessControl(login, token) {
   const headers = { 'Accept': 'application/vnd.github+json', 'Authorization': 'token ' + token };
   const candidates = [`${login}/zen-panel`, DEFAULT_REPO];
   for (const repo of candidates) {
     try {
       const r = await fetch(`${GH}/repos/${repo}`, { headers });
       if (!r.ok) continue;
       const w = await fetch(`${GH}/repos/${repo}/contents/.github/workflows/agent.yml`, { headers });
       if (w.ok) return repo;
     } catch (e) { /* try the next candidate */ }
   }
   return DEFAULT_REPO;
 }

 function switchTo(index) {
   STORE.active = index;
   saveStore(STORE);
   REPOS = [];
   ACT_REPO = ctlRepo();
   if ($('act-repo')) $('act-repo').textContent = ACT_REPO;
   loadAccount();
   if (page === 'repo') loadRepos(true);
   if (page === 'act')  loadActions(true);
   refresh();
 }

 function removeAccount(index) {
   const a = STORE.accounts[index];
   if (!a) return;
   if (!confirm('Убрать ' + (a.login || 'этот аккаунт') + ' с этого устройства?\n\n' +
                'Токен удаляется только здесь — на GitHub он продолжает действовать. ' +
                'Отозвать его можно в настройках GitHub.')) return;
   STORE.accounts.splice(index, 1);
   if (STORE.active >= STORE.accounts.length) STORE.active = Math.max(0, STORE.accounts.length - 1);
   saveStore(STORE);
   switchTo(STORE.active);
 }

 // The control repository can be set by hand: a fork under a different name, or
 // somebody else's repository the token can reach.
 function setControl() {
   const a = acct();
   if (!a) { alert('Сначала добавьте аккаунт.'); return; }
   const value = prompt('Репозиторий с workflow (owner/name):', a.control || DEFAULT_REPO);
   if (!value) return;
   const clean = value.trim().replace(/^https?:\/\/github\.com\//, '').replace(/\.git$/, '');
   if (!/^[\w.-]+\/[\w.-]+$/.test(clean)) { alert('Ожидается owner/name.'); return; }
   a.control = clean;
   saveStore(STORE);
   switchTo(STORE.active);
 }

 // A single place for API calls so an expired token reports itself once, in
 // words, instead of every panel silently rendering empty.
 // Conditional GETs: GitHub answers 304 without a body and - the point -
 // without spending quota, so a quiet re-poll costs nothing.
 const ETAGS = new Map();
 async function api(url, opts) {
   const o = Object.assign({ headers: hdr() }, opts || {});
   const isGet = !o.method || o.method === 'GET';
   // The t= buster changes every call; the etag is per resource, not per URL.
   const ekey = String(url).replace(/[?&]t=\d+/, '');
   const slot = isGet && ETAGS.get(ekey);
   if (slot && slot.etag) o.headers['If-None-Match'] = slot.etag;
   const r = await fetch(url, o);
   if (r.status === 304 && slot) return slot.body;
   if (r.status === 401) throw new Error('Токен недействителен (401). Вставьте новый.');
   if (r.status === 403) {
     const err = new Error('403: лимит запросов или нет прав. Без токена лимит 60/час.' + unbanHint(r));
     err.is403 = true;
     err.unbanMs = unbanMs(r);
     throw err;
   }
   if (r.status === 429) {
     const err = new Error('429: слишком много запросов — GitHub притормозил. Закройте лишние клиенты/VPN и обновите.' + unbanHint(r));
     err.is403 = true;
     err.unbanMs = unbanMs(r);
     throw err;
   }
   if (r.status === 404) throw new Error('404: не найдено или не видно этому токену.');
   if (!r.ok) throw new Error('HTTP ' + r.status);
   const body = await r.json();
   if (isGet) {
     try { const et = r.headers.get('etag'); if (et) ETAGS.set(ekey, { etag: et, body }); } catch (e) {}
   }
   return body;
 }

 // When the API will answer again, so a 403 pauses the pollers instead
 // of feeding the ban they are already under.
 function unbanMs(r) {
   try {
     const ra = +r.headers.get('retry-after') || 0;
     if (ra) return ra * 1000;
     const reset = +r.headers.get('x-ratelimit-reset') || 0;
     if (reset) return Math.max(0, reset * 1000 - Date.now());
   } catch (e) {}
   return 10 * 60 * 1000;
 }

 function unbanHint(r) {
   try {
     const ra = r.headers.get('retry-after');
     if (ra) return ` Пауза ${ra} с.`;
     const reset = +r.headers.get('x-ratelimit-reset') || 0;
     if (reset) {
       const t = new Date(reset * 1000);
       const hh = String(t.getHours()).padStart(2, '0'), mm = String(t.getMinutes()).padStart(2, '0');
       return ` Пауза до ${hh}:${mm}.`;
     }
   } catch (e) {}
   return '';
 }

 // ── navigation ──────────────────────────────────────────────────────
 let page = 'sess';
 function go(p) {
   page = p;
   for (const id of ['acc','repo','files','act','sess','apps','apk']) {
     const el = $('p-' + id); if (el) el.classList.toggle('on', id === p);
     const tb = $('t-' + id); if (tb) tb.classList.remove('on');
   }
   // The files page is a drill-in of Repos, so it keeps that tab lit.
   const lit = p === 'files' ? 'repo' : p;
   if ($('t-' + lit)) $('t-' + lit).classList.add('on');
   window.scrollTo(0, 0);
   if (p === 'acc')  loadAccount();
   if (p === 'repo') loadRepos();
   if (p === 'act')  { loadActions(); pollWatch(); }
   if (p === 'sess') refresh();
   if (p === 'apps') appsLoad();
   if (p === 'apk')  { refresh(); loadPanelApk(); }
 }

 // ── account ─────────────────────────────────────────────────────────
 async function loadAccount() {
   const box = $('acc');
   const rows = [];

   // The switcher comes first: with several accounts stored, which one is
   // active decides what every other tab shows, so it should be the first
   // thing on screen rather than a detail under the profile.
   if (STORE.accounts.length) {
     rows.push('<div style="margin-bottom:10px">' + STORE.accounts.map((a, i) => `
       <div class="item" style="${i === STORE.active ? 'background:#1d1d29;border-radius:10px' : ''}">
         <div class="ico">${i === STORE.active ? '●' : '○'}</div>
         <div class="grow" onclick="switchTo(${i})">
           <div class="name">${esc(a.login || 'без имени')}${
             i === STORE.active ? ' <span class="pill ok">активен</span>' : ''}</div>
           <div class="meta">workflow: ${esc(a.control || DEFAULT_REPO)}</div>
         </div>
         <button class="ghost small" onclick="event.stopPropagation();removeAccount(${i})">✕</button>
       </div>`).join('') + '</div>');
   }

   try {
     // /user needs a token; without one fall back to the public profile so the
     // page still says whose repositories it is showing.
     const u = tok() ? await api(`${GH}/user`) : await api(`${GH}/users/${DEFAULT_OWNER}`);
     if (tok() && acct() && !acct().login) {
       // A token carried over from the old single-token panel has no name yet.
       acct().login = u.login; acct().avatar = u.avatar_url || ''; saveStore(STORE);
     }
     rows.push(`
       <div class="head">
         <img class="avatar" src="${esc(u.avatar_url)}" alt="">
         <div class="grow">
           <div style="font-weight:700">${esc(u.login)}</div>
           <div class="note" style="margin:0">${esc(u.name || '')}</div>
           <a href="#" onclick="openExternal(\'${esc(u.html_url)}\');return false">${esc(u.html_url)}</a>
         </div>
       </div>
       <table style="margin-top:10px">
         <tr><td>Репозитории</td><td>${u.public_repos ?? '—'} публичных${
           u.total_private_repos != null ? ' · ' + u.total_private_repos + ' приватных' : ''}</td></tr>
         <tr><td>Токен</td><td>${tok()
           ? '<span class="pill ok">есть</span>' +
             (acct() && acct().scopes ? ' <span class="note">' + esc(acct().scopes) + '</span>' : '')
           : '<span class="pill idle">нет</span> <span class="note">только чтение публичного</span>'}</td></tr>
         <tr><td>Workflow</td><td><code>${esc(ctlRepo())}</code>
           <div class="note"><a onclick="setControl()">сменить репозиторий</a> —
             отсюда запускаются сессии и сборки</div></td></tr>
       </table>`);
     box.innerHTML = rows.join('');
   } catch (e) {
     box.innerHTML = rows.join('') + `<div class="danger">${esc(e.message)}</div>`;
   }
 }


 // ── repositories ────────────────────────────────────────────────────
 let REPOS = [];
 async function loadRepos(force) {
   const box = $('repos');
   if (REPOS.length && !force) { renderRepos(); return; }
   box.innerHTML = '<span class="spin">загрузка…</span>';
   try {
     // With a token: everything it can see, newest first. Without: the public
     // ones, which is still enough to browse this fork.
     const url = tok()
       ? `${GH}/user/repos?per_page=100&sort=updated&affiliation=owner,collaborator,organization_member`
       : `${GH}/users/${owner()}/repos?per_page=100&sort=updated`;
     REPOS = await api(url);
     renderRepos();
   } catch (e) {
     box.innerHTML = `<div class="danger">${esc(e.message)}</div>`;
   }
 }

 function renderRepos() {
   const q = ($('repo-filter').value || '').toLowerCase();
   const list = REPOS.filter(r => !q || r.full_name.toLowerCase().includes(q));
   $('repos').innerHTML = list.length ? list.map(r => `
     <div class="item">
       <div class="ico" title="${r.private ? 'приватный' : 'публичный'}"
            onclick="setVisibility('${esc(r.full_name)}', ${r.private ? 'false' : 'true'})"
            style="cursor:pointer">${r.private ? '🔒' : '🌐'}</div>
       <div class="grow" onclick="openRepo('${esc(r.full_name)}')">
         <div class="name">${esc(r.name)}</div>
         <div class="meta">${esc(r.description || 'без описания').slice(0, 70)}</div>
         <div class="meta">${esc(r.default_branch)} · обновлён ${ago(r.updated_at)}</div>
       </div>
       <div class="ico" onclick="openRepo('${esc(r.full_name)}')">›</div>
     </div>`).join('')
     : '<span class="note">ничего не найдено</span>';
 }

 // ── file browser ────────────────────────────────────────────────────
 let CUR = { repo: ctlRepo(), path: '', branch: '' };

 function openRepo(full) {
   CUR = { repo: full, path: '', branch: '' };
   $('act-repo').textContent = full;
   ACT_REPO = full;
   openPath('');
 }

 // Flip a repository between private and public.
 //
 // Going public is the irreversible-feeling direction - the history becomes
 // readable by anyone, including any secret ever committed to it - so it asks
 // twice and says that plainly. Going private is offered too, since the useful
 // operation is "change this", not "publish this".
 async function setVisibility(full, makePrivate) {
   if (!tok()) { alert('Нужен токен с правом repo.'); return; }
   const warning = makePrivate
     ? 'Сделать ' + full + ' приватным?\n\nGitHub Pages на бесплатном плане ' +
       'работает только для публичных репозиториев — панель по адресу github.io ' +
       'перестанет открываться.'
     : 'Сделать ' + full + ' публичным?\n\nВся история станет видна любому: ' +
       'файлы, коммиты, и любой токен или пароль, который когда-либо попадал ' +
       'в репозиторий. Ветка session-state с паролями сессий — тоже.';
   if (!confirm(warning)) return;
   if (!makePrivate && !confirm('Точно? Это видно всему интернету сразу.')) return;

   try {
     const r = await fetch(`${GH}/repos/${full}`, {
       method: 'PATCH', headers: hdr(),
       body: JSON.stringify({ private: !!makePrivate })
     });
     if (r.status === 403) throw new Error('403: у токена нет права repo, ' +
       'либо смена видимости запрещена настройками организации.');
     if (r.status === 422) throw new Error('422: GitHub отказал — ' +
       'обычно это лимит плана на приватные репозитории.');
     if (!r.ok) throw new Error('HTTP ' + r.status + ' ' + (await r.text()).slice(0, 200));
     alert(full + ' теперь ' + (makePrivate ? 'приватный' : 'публичный') + '.');
     await loadRepos(true);
   } catch (e) {
     alert('Не вышло: ' + e.message);
   }
 }

 async function openPath(path) {
   CUR.path = path;
   go('files');
   $('files-title').textContent = CUR.repo.split('/')[1];
   const parts = path ? path.split('/') : [];
   let acc = '';
   const crumbs = ['<a onclick="openPath(\'\')">' + esc(CUR.repo) + '</a>'];
   for (const p of parts) {
     acc = acc ? acc + '/' + p : p;
     crumbs.push(`<a onclick="openPath('${esc(acc)}')">${esc(p)}</a>`);
   }
   $('crumb').innerHTML = crumbs.join(' / ') +
     ` · <a href="#" onclick="openExternal('https://github.com/${esc(CUR.repo)}/tree/HEAD/${esc(path)}');return false">на GitHub</a>`;

   const box = $('files');
   box.innerHTML = '<span class="spin">загрузка…</span>';
   try {
     const items = await api(`${GH}/repos/${CUR.repo}/contents/${encodeURI(path)}`);
     if (!Array.isArray(items)) { showFile(items); return; }
     items.sort((a, b) => (a.type === b.type)
       ? a.name.localeCompare(b.name)
       : (a.type === 'dir' ? -1 : 1));
     const up = path
       ? `<div class="item" onclick="openPath('${esc(path.split('/').slice(0, -1).join('/'))}')">
            <div class="ico">↰</div><div class="grow"><div class="name">..</div></div></div>`
       : '';
     box.innerHTML = up + items.map(it => `
       <div class="item" onclick="${it.type === 'dir'
           ? `openPath('${esc(it.path)}')`
           : `openFile('${esc(it.path)}')`}">
         <div class="ico">${it.type === 'dir' ? '▸' : '·'}</div>
         <div class="grow">
           <div class="name">${esc(it.name)}</div>
           ${it.type === 'file' ? `<div class="meta">${kb(it.size)}</div>` : ''}
         </div>
         <div class="ico">›</div>
       </div>`).join('');
   } catch (e) {
     box.innerHTML = `<div class="danger">${esc(e.message)}</div>`;
   }
 }

 async function openFile(path) {
   const box = $('files');
   box.innerHTML = '<span class="spin">загрузка…</span>';
   try {
     const f = await api(`${GH}/repos/${CUR.repo}/contents/${encodeURI(path)}`);
     showFile(f);
   } catch (e) {
     box.innerHTML = `<div class="danger">${esc(e.message)}</div>`;
   }
 }

 function showFile(f) {
   const back = f.path.split('/').slice(0, -1).join('/');
   const raw = `https://github.com/${CUR.repo}/blob/HEAD/${f.path}`;
   let body;
   if (f.size > 400000) {
     body = '<div class="note">Файл больше 400 КБ — открывайте на GitHub.</div>';
   } else if (/\.(png|jpe?g|gif|webp|svg)$/i.test(f.name)) {
     body = `<img style="max-width:100%;border-radius:10px" src="${esc(f.download_url)}" alt="">`;
   } else if (f.content) {
     let text;
     try { text = decodeURIComponent(escape(atob(f.content.replace(/\n/g, '')))); }
     catch (e) { text = atob(f.content.replace(/\n/g, '')); }
     body = `<pre>${esc(text)}</pre>`;
   } else {
     body = '<div class="note">Двоичный файл.</div>';
   }
   $('crumb').innerHTML =
     `<a onclick="openPath('${esc(back)}')">↰ назад</a> · ${esc(f.path)} · ${kb(f.size)} ·
      <a href="#" onclick="openExternal(\'${esc(raw)}\');return false">на GitHub</a>`;
   $('files').innerHTML = body;
 }

 // ── actions ─────────────────────────────────────────────────────────
 let ACT_REPO = ctlRepo();

 // ── live progress ───────────────────────────────────────────────────
 //
 // Watching a build meant leaving for github.com and hunting for the running
 // step. This polls the jobs endpoint, which is CORS-open, and shows each step
 // with a tick, a spinner and how long it has taken.
 //
 // It deliberately does not show log text: GitHub only publishes a job's log
 // after the job finishes - the endpoint 404s with BlobNotFound while it runs -
 // so a "live log" here would be an empty box pretending to work. Steps do
 // update in real time, and the link to the real log is one tap away.

 let watchTimer = null;
 let watchPaused = false;
 let sessPausedUntil = 0;   // a 403 parks the Sessions auto-refresh until this time
 const WATCH_NAMES = ['Build APK', 'Tests', 'Panel APK', 'Build Zen Panel APK', 'Zen agent', 'Remote session', 'Desks', 'OpenCode'];

 function fmtSecs(sec) {
   if (sec < 60) return sec + ' с';
   const m = Math.floor(sec / 60), r = sec % 60;
   return m + ' мин' + (r ? ' ' + r + ' с' : '');
 }

 function stepIcon(st) {
   if (st.status === 'in_progress') return '<span style="color:var(--amber)">◐</span>';
   if (st.status === 'queued' || st.status === 'pending') return '<span style="color:var(--dim)">○</span>';
   if (st.conclusion === 'success') return '<span style="color:var(--green)">✓</span>';
   if (st.conclusion === 'skipped') return '<span style="color:var(--dim)">–</span>';
   return '<span style="color:var(--red)">✕</span>';
 }

 function stepSecs(st) {
   if (!st.started_at) return null;
   const from = new Date(st.started_at).getTime();
   const to = st.completed_at ? new Date(st.completed_at).getTime() : Date.now();
   return Math.max(0, Math.round((to - from) / 1000));
 }

 async function pollWatch() {
   const card = $('watch-card'), box = $('watch');
   if (!card || !box) return;
   let runs = [];
   try { runs = (await api(`${CTL()}/actions/runs?per_page=15`)).workflow_runs || []; }
   catch (e) { pauseWatchOn403(e); return; }

   const live = runs.filter(r => r.status !== 'completed' && WATCH_NAMES.includes(r.name));
   if (!live.length) {
     card.style.display = 'none';
     box.innerHTML = '';
     return;
   }
   card.style.display = '';

   const parts = [];
   for (const r of live.slice(0, 3)) {
     let jobs = [];
     try { jobs = (await api(`${CTL()}/actions/runs/${r.id}/jobs`)).jobs || []; }
     catch (e) { if (pauseWatchOn403(e)) return; continue; }
     for (const j of jobs) {
       if (j.conclusion === 'skipped') continue;
       const done = j.steps.filter(x => x.status === 'completed').length;
       const total = j.steps.length;
       const cur = j.steps.find(x => x.status === 'in_progress');
       const elapsed = j.started_at
         ? Math.round((Date.now() - new Date(j.started_at).getTime()) / 1000) : 0;

       parts.push(`
         <div style="margin-bottom:12px">
           <div><b>${esc(r.name)}</b> #${r.run_number} ${pill(r)}
             <span class="note">· ${fmtSecs(elapsed)} · ${done}/${total}</span></div>
           <div style="height:6px;background:#22222e;border-radius:99px;margin:6px 0">
             <div style="height:6px;width:${Math.round(done / Math.max(1, total) * 100)}%;
                  background:var(--cyan);border-radius:99px;transition:width .4s"></div>
           </div>
           ${cur ? `<div class="note" style="margin:0">сейчас: ${esc(cur.name)}
                     ${stepSecs(cur) != null ? '· ' + fmtSecs(stepSecs(cur)) : ''}</div>` : ''}
           <details style="margin-top:6px">
             <summary>все шаги</summary>
             ${j.steps.map(st => `<div style="font-size:12.5px;padding:2px 0">
               ${stepIcon(st)} ${esc(st.name)}
               ${stepSecs(st) != null ? `<span class="note">· ${fmtSecs(stepSecs(st))}</span>` : ''}
             </div>`).join('')}
           </details>
           <div class="row" style="margin-top:6px">
             <a class="note" href="#" onclick="openExternal(\'${esc(r.html_url)}\');return false">полный лог на GitHub</a>
           </div>
         </div>`);
     }
   }
   box.innerHTML = parts.join('') ||
     '<span class="note">запуск ставится в очередь…</span>';
 }

 function pauseWatchOn403(e) {
   if (!e || !e.is403) return false;
   watchPaused = true;
   const b = $('watch-btn'); if (b) b.textContent = 'продолжить';
   const card = $('watch-card'), box = $('watch');
   if (card && box) { card.style.display = ''; box.innerHTML = `<div class="danger">${esc(e.message)}</div>`; }
   return true;
 }

 function toggleWatch() {
   watchPaused = !watchPaused;
   const b = $('watch-btn');
   if (b) b.textContent = watchPaused ? 'продолжить' : 'пауза';
   if (!watchPaused) pollWatch();
 }

 function startWatching() {
   if (watchTimer) return;
   pollWatch();
   // Five seconds: fast enough to feel live, slow enough that the hourly rate
   // limit is never in danger even with the Actions tab left open.
   watchTimer = setInterval(() => {
     // Jobs polling is heavy and used to freeze the session tab. Only the
     // Actions page needs per-step ticks; the session tab has its own boot log.
     if (!watchPaused && page === 'act' && !document.hidden) pollWatch();
   }, 8000);
 }

 async function loadActions(force) {
   $('act-repo').textContent = ACT_REPO;
   const wbox = $('workflows'), rbox = $('runs');
   wbox.innerHTML = '<span class="spin">загрузка…</span>';
   try {
     const d = await api(`${GH}/repos/${ACT_REPO}/actions/workflows?per_page=50`);
     const list = (d.workflows || []).filter(w => w.state === 'active');
     wbox.innerHTML = list.length ? list.map(w => {
       const file = w.path.split('/').pop();
       return `<div class="item">
         <div class="ico">▶</div>
         <div class="grow" onclick="openPath('${esc(w.path)}')">
           <div class="name">${esc(w.name)}</div>
           <div class="meta">${esc(file)}</div>
         </div>
         <button class="ghost small" onclick="event.stopPropagation();runIn('${esc(ACT_REPO)}','${esc(file)}')">Запустить</button>
       </div>`;
     }).join('') : '<span class="note">workflow нет</span>';
   } catch (e) {
     wbox.innerHTML = `<div class="danger">${esc(e.message)}</div>`;
   }

   rbox.innerHTML = '<span class="spin">загрузка…</span>';
   try {
     const d = await api(`${GH}/repos/${ACT_REPO}/actions/runs?per_page=12`);
     const rs = d.workflow_runs || [];
     rbox.innerHTML = rs.length ? '<table>' + rs.map(r => `<tr>
       <td>#${r.run_number}</td>
       <td><a href="#" onclick="openExternal(\'${esc(r.html_url)}\');return false">${esc(r.name)}</a> ${pill(r)}
         <div class="note">${ago(r.updated_at)}${
           r.status !== 'completed' && tok()
             ? ` · <a onclick="stopRun(${r.id},'${esc(ACT_REPO)}')">остановить</a>` : ''}${
           (r.status === 'completed' || r.status === 'cancelled') && tok()
             ? ` · <a onclick="rerunRun(${r.id},'${esc(ACT_REPO)}')">перезапустить</a>` : ''}</div></td>
       </tr>`).join('') + '</table>' : '<span class="note">запусков нет</span>';
   } catch (e) {
     rbox.innerHTML = `<div class="danger">${esc(e.message)}</div>`;
   }
 }

 async function runIn(repo, wf) {
   if (!tok()) { alert('Нужен токен, чтобы запускать.'); return; }
   const r = await fetch(`${GH}/repos/${repo}/actions/workflows/${wf}/dispatches`, {
     method: 'POST', headers: hdr(), body: JSON.stringify({ ref: 'main' })
   });
   if (r.status === 204) { alert('Запущено.'); setTimeout(() => loadActions(true), 2500); return; }
   // A workflow with required inputs, or one without workflow_dispatch, says so
   // in the body; showing it beats a bare status code.
   alert('Не вышло: ' + r.status + ' ' + (await r.text()).slice(0, 300));
 }

 async function run(wf, inputs) {
   if (!tok()) { alert('Сначала вставьте токен — без него запуск невозможен.'); return; }
   const r = await dispatchWorkflow(wf, inputs);
   alert(r.status === 204 ? 'Запущено.' : 'Не вышло: ' + r.status + ' ' + await r.text());
   setTimeout(refresh, 2500);
 }

 // Dispatch into the account's control repo, then the shared default if that
 // repo has no such workflow (typical after a leftover /symbiosis control).
 async function dispatchWorkflow(wf, inputs) {
   const body = JSON.stringify({ ref: 'main', inputs: inputs || {} });
   const post = repo => fetch(`${GH}/repos/${repo}/actions/workflows/${wf}/dispatches`, {
     method: 'POST', headers: hdr(), body
   });
   let r = await post(ctlRepo());
   if (r.status === 404 && ctlRepo() !== DEFAULT_REPO) {
     const fallback = await post(DEFAULT_REPO);
     if (fallback.status === 204) {
       const a = acct();
       if (a) { a.control = DEFAULT_REPO; saveStore(STORE); }
       return fallback;
     }
   }
   return r;
 }

 // Runner for a dispatched launch: GitHub-hosted by default, or the labels of
 // the user's own machine (see pc-local/runner) when they pick it.
 function runnerInputs() {
   const own = confirm('Где выполнять?\n\nОК — раннеры GitHub\nОтмена — свой ПК (self-hosted)') ? '' : 'self-hosted';
   return { runner_linux: own || 'ubuntu-latest', runner_windows: own || 'windows-latest' };
 }

 // ── sessions ────────────────────────────────────────────────────────
 const QUEUED_RUN_STATUSES = ['queued', 'requested', 'waiting', 'pending'];
 const runIsQueued = r => !!r && QUEUED_RUN_STATUSES.includes(r.status);
 const runningFirst = rs => rs.slice().sort((a, b) => {
   const ai = a.status === 'in_progress' ? 0 : 1;
   const bi = b.status === 'in_progress' ? 0 : 1;
   return ai - bi || new Date(a.created_at || 0) - new Date(b.created_at || 0);
 });
 const liveAgents   = rs => runningFirst(rs.filter(r => r.name === 'Zen agent' && r.status !== 'completed'));
 const liveOpencode = rs => runningFirst(rs.filter(r => (r.name === 'OpenCode' || r.name === 'opencode')
                                           && r.status !== 'completed'));
 const liveHub      = rs => runningFirst(rs.filter(r => r.name === 'NPM Hub' && r.status !== 'completed'));
 const liveDesktops = rs => runningFirst(rs.filter(r => (r.name === 'Remote session' || r.name === 'Desks')
                                           && r.status !== 'completed'));

 async function currentRuns() {
   try { return (await api(`${CTL()}/actions/runs?per_page=100`)).workflow_runs || []; }
   catch (e) { return []; }
 }

 // The address a session is actually on, not the one it hoped for.
 //
 // This is what produced the black screen. The free ngrok plan allows one
 // tunnel; when the reserved domain is already taken the workflow falls back to
 // a generated address and prints that, while the panel opened the reserved one
 // unconditionally and served whatever else was there - a 404, i.e. a blank
 // page with no explanation. Everything now comes from session.json.
 let LIVE = null;
 let LAST_RUNS = [];

 let previewOpen = false;
 let previewTab = 'screen';   // screen | term

 function renderPreview() {
   const box = $('preview');
   const card = $('screen-card');
   if (!box || !card) return;

   // VNC desks are gone; the only embeddable screen left is a hub launcher root.
   const liveSlot = (LIVE && LIVE._slot) || '';
   const isHubLive = liveSlot.startsWith('hub') || (LIVE && (LIVE.hubUrl || /npm-hub/i.test(LIVE.kind || '')));
   const screen = isHubLive ? (LIVE.hubUrl || LIVE.terminal || LIVE.url || null) : null;
   const term = LIVE && LIVE.terminal ? LIVE.terminal : null;
   const agent = null; // never embed the chat SPA in a 200px preview — it janks the WebView

   // Windows RDP has nothing embeddable: it is not HTTP. Saying so beats an
   // empty black box that looks broken.
   if (!screen && !term && !agent) {
     if (LIVE && LIVE.rdpHost) {
       card.style.display = '';
       box.innerHTML = '<span class="note">Windows по RDP — встроить в браузер нельзя. ' +
         'Адрес, логин и пароль ниже; открывайте в Microsoft Remote Desktop.</span>';
     } else {
       card.style.display = 'none';
     }
     previewOpen = false;
     return;
   }

   card.style.display = '';
   if (previewTab === 'term' && !term) previewTab = 'screen';
   const url0 = previewTab === 'term' ? term : (screen || agent);
   // Session rows never carry ?zt= (gate tokens live only in this browser's
   // localStorage); without the wrap the frame shows a bare 401 instead.
   const url = (url0 && isHubLive) ? hubUrlWithToken(url0, liveSlot) : url0;
   const ztMissing = isHubLive && url0 && !(liveSlot && HUB_TOKENS[liveSlot]);
   const ztHint = ztMissing
     ? `<div class="note" style="margin-top:8px">Хаб закрыт токеном, которого нет в этом браузере — вместо лаунчера будет ошибка «hub token?». <button class="ghost small" onclick="openDeskInPanel(liveSlotOf('hub'))">Открыть стол</button> — панель предложит перезапустить хаб или ввести токен вручную.</div>`
     : '';

   const tabs = `
     <div class="row" style="margin-bottom:8px">
       ${screen || agent ? `<button class="${previewTab === 'screen' ? '' : 'ghost '}small"
         onclick="previewTab='screen';renderPreview()">${agent && !screen ? 'Агент' : 'Экран'}</button>` : ''}
       ${term ? `<button class="${previewTab === 'term' ? '' : 'ghost '}small"
         onclick="previewTab='term';renderPreview()">Терминал</button>` : ''}
     </div>`;

   if (!previewOpen) {
     box.innerHTML = tabs + `
       <div style="position:relative;border:1px solid var(--line);border-radius:10px;
            overflow:hidden;background:#000;height:200px">
         <iframe src="${esc(url)}" style="border:0;width:200%;height:400px;
                 transform:scale(.5);transform-origin:0 0" scrolling="no"
                 sandbox="allow-scripts allow-same-origin allow-forms"></iframe>
         <div onclick="expandPreview()" style="position:absolute;inset:0;cursor:pointer"></div>
       </div>
       <div class="row" style="margin-top:8px">
         <button class="ghost small" onclick="expandPreview()">Развернуть</button>
         <button class="ghost small" onclick="openExternal('${esc(url)}')">Ссылка</button>
       </div>
       ${ztHint}`;
   } else {
     box.innerHTML = tabs + `
       <iframe src="${esc(url)}" style="border:1px solid var(--line);border-radius:10px;
               width:100%;height:70vh;background:#000"
               sandbox="allow-scripts allow-same-origin allow-forms"></iframe>
       <div class="row" style="margin-top:8px">
         <button class="ghost small" onclick="collapsePreview()">Свернуть</button>
         <button class="ghost small" onclick="openExternal('${esc(url)}')">Ссылка</button>
       </div>
       ${ztHint}`;
   }
 }

 function expandPreview()   { previewOpen = true;  renderPreview(); }
 function collapsePreview() { previewOpen = false; renderPreview(); }

 // ── two desks, side by side ─────────────────────────────────────────
 //
 // The Desks workflow publishes one file per desk - session-linux.json and
 // session-windows.json - so the two never overwrite each other. That split
 // exists because the old single mailbox meant only one desk could be live at
 // a time, and because free ngrok allowed exactly one tunnel. cloudflared quick
 // tunnels have no such limit, so both desks are genuinely up at once.
 //
 // Neither has a password. There is nothing to copy and nothing to type: the
 // button opens the desk and it connects on its own.
 let DESKS = { linux: null, windows: null, 'agent-linux': null, 'agent-windows': null, agent: null, 'opencode-linux': null, 'opencode-windows': null, opencode: null, 'hub-linux': null, 'hub-windows': null, hub: null };
 let MODELS = { linux: null, windows: null, 'agent-linux': null, 'agent-windows': null, agent: null, 'opencode-linux': null, 'opencode-windows': null, opencode: null, 'hub-linux': null, 'hub-windows': null, hub: null };
 let deskOpen = null;   // a DESK_SLOTS entry ('agent-linux', 'hub', …) | null

 // The signature of what is currently drawn. Rebuilding the card replaces the
 // iframes, and a replaced iframe reconnects from scratch - which is exactly
 // the "black for a couple of seconds, then fine again" that showed up on the
 // phone, on both desks, on a timer. Measured while it was happening: the
 // Windows stream itself was steady at 4.35 fps with a median 0.23s gap and no
 // disconnects, so nothing was wrong with either desk. refresh() simply ran
 // every 30 seconds and rewrote innerHTML underneath them.
 //
 // So the DOM is only rebuilt when something that matters actually changes -
 // an address, a desk appearing or going away, the expanded view. The minute
 // counter updates on its own, as text.
 let deskSig = '';

 async function loadDesks() {
   const box = $('desks');
   const card = $('desks-card');
   if (!box || !card) return;

   // The session page refreshes itself every 30 seconds, and this function
   // rewrites the card's innerHTML. With the chat embedded that would tear down
   // the iframe and reload the hub mid-sentence - losing whatever was typed and
   // scrolling the conversation back to the top. The open chat is left exactly
   // as it is; the poll still runs, it just does not touch this card.
   //
   // The open overlay is never rebuilt by a poll - only synced (tabs added or
   // dropped), because rebuilding tears down the iframes and a chat loses what
   // was typed. The reads below still run: sync needs fresh DESKS.
   const readFile = async (name, checkAge) => {
     // The branch was reorganised into folders (live/, models/, snapshots/,
     // history/<date>/<weekday>/). New path first, old root second: a branch
     // that has not been migrated yet keeps working unchanged.
     for (const path of [`live/${name}`, name]) {
     try {
       const f = await api(
         `${CTL()}/contents/${path}?ref=session-state&t=${Date.now()}`);
       const s = JSON.parse(decodeURIComponent(escape(
         atob((f.content || '').replace(/\n/g, '')))));
       if (checkAge) {
         // A runner killed hard never clears its file, so an old entry lingers
         // and would advertise a desk that stopped answering hours ago.
         const born = Date.parse(s.startedAt || '');
         const age = (Date.now() - born) / 60000;
         if (s.state === 'ended' || !Number.isFinite(born) || age > 361) return null;
         s._age = Math.round(age);
       }
       return s;
     } catch (e) { /* 404 = try the legacy name, a rate limit = show no desks here */ }
     }
     return null;
   };
   const read = async slot => readFile(`session-${slot}.json`, true);
   const readModels = async slot => readFile(`models-${slot}.json`, false);

   // Session files first, models only for slots that are actually live: most
   // models files do not exist, and a 404 still costs a request.
   const sess = await Promise.all(DESK_SLOTS.map(read));
   const liveSlots = DESK_SLOTS.filter((s, i) => sess[i]);
   const marr = await Promise.all(liveSlots.map(readModels));
   DESKS = {}; MODELS = {};
   for (const s of DESK_SLOTS) { DESKS[s] = null; MODELS[s] = null; }
   DESK_SLOTS.forEach((s, i) => { if (sess[i]) sess[i]._slot = s; DESKS[s] = sess[i]; });
   liveSlots.forEach((s, i) => { MODELS[s] = marr[i]; });

   if (deskOpen && document.getElementById('desk-overlay')) { syncDeskOverlay(); return; }

   if (!liveSlots.length) {
     card.style.display = 'none';
     deskSig = '';
     collapseDesks();
     return;
   }
   card.style.display = '';

   const ageLine = s => `${s.agentUrl ? 'по ссылке с токеном' : 'без пароля'} · идёт ${s._age} мин · осталось ~${Math.max(0, 360 - s._age)} мин`;
   // One line per session: most-used model plus live/total roster counts.
   // The roster shape is the agent's ~/.zen_free_models.json: { models: { id:
   // { state, ok, fails } } }. Anything else (opencode config) shows its ui.
   const modelText = slot => {
     const m = MODELS[slot];
     if (!m) return '';
     if (m.hubCount != null) return `Модели: ${m.hubCount} (${m.hubFree | 0} бесплатных)`;
     const entries = Object.entries((m && m.models) || {});
     if (!entries.length) return m.ui ? `OpenCode · ${m.ui}` : (m.kind ? String(m.kind) : '');
     const live = entries.filter(([, e]) => e && e.state !== 'dead').length;
     const top = entries.filter(([, e]) => e && (e.ok | 0) > 0)
       .sort((a, b) => (b[1].ok | 0) - (a[1].ok | 0))[0] || entries[0];
     return `Модель: ${top[0]} · ростер ${live}/${entries.length}`;
   };

   // Nothing structural changed: touch the counters and leave the iframes be.
   const sig = JSON.stringify([deskOpen, ...DESK_SLOTS.map(s => {
     const v = DESKS[s];
     return v && [v.deskUrl || v.agentUrl || v.hubUrl || v.url, v.terminal || '', v.runId || ''];
   })]);
   if (sig === deskSig) {
     for (const slot of DESK_SLOTS) {
       const s = DESKS[slot];
       const el = $('desk-age-' + slot);
       if (el && s) el.textContent = ageLine(s);
       const ml = $('desk-model-' + slot);
       if (ml) ml.textContent = modelText(slot);
     }
     return;
   }
   deskSig = sig;

   const tile = (slot, s, title) => {
     if (!s) return `
       <div style="flex:1;min-width:150px;border:1px dashed var(--line);border-radius:10px;
            padding:12px;opacity:.55">
         <b>${title}</b><div class="note" style="margin-top:4px">не запущен</div>
       </div>`;
     const url = (slot === 'hub' || slot.startsWith('hub-')) ? deskSlotUrl(slot) : (s.deskUrl || s.url || '');
     // No live thumbnail. A live iframe or MJPEG in every tile froze the
     // whole WebView on a phone; the desk is opened only when asked.
     return `
       <div style="flex:1;min-width:150px;border:1px solid var(--line);border-radius:10px;
            padding:12px">
         <b>${title}</b>
         <div class="note" style="margin:4px 0 8px" id="desk-age-${slot}">${esc(ageLine(s))}</div>
         <div class="note" style="margin:0 0 8px" id="desk-model-${slot}">${esc(modelText(slot))}</div>
         <div class="desk-ph" onclick="expandDesk('${slot}')">${title} · нажмите «Открыть»</div>
         <div style="height:8px"></div>
         <div class="row">
           <button class="small" onclick="expandDesk('${slot}')">Открыть здесь</button>
           <button class="ghost small" onclick="openExternal('${esc(url)}')">Ссылка</button>
           <button class="ghost small" onclick="saveSession('${slot}')">Сохранить</button>
         </div>
         ${s.terminal ? `<div class="row" style="margin-top:6px">
           <button class="ghost small" onclick="openExternal('${esc(s.terminal)}')">Ссылка</button></div>` : ''}
         ${s.runId && tok() ? `<div class="row" style="margin-top:6px">
           <button class="ghost small" onclick="stopRun(${s.runId})">Выключить</button></div>` : ''}
       </div>`;
   };

   if (deskOpen && DESKS[deskOpen]) {
     renderDeskOverlay();
     box.innerHTML = '<div class="note">Открыто вторым слоем — переключайте вкладки сверху.</div>';
   } else {
     // The agent has no screen to show - it is a chat page - so it gets a row
     // of its own rather than an empty black thumbnail pretending to be a desk.
     const chatRow = (slot, s, title) => !s ? '' : `
       <div style="margin-top:10px;border:1px solid var(--line);border-radius:10px;padding:12px">
         <b>${esc(title)}</b>
         <div class="note" style="margin:4px 0 8px" id="desk-age-${slot}">${esc(ageLine(s))}</div>
         <div class="note" style="margin:0 0 8px" id="desk-model-${slot}">${esc(modelText(slot))}</div>
         <div class="row">
           <button class="small" onclick="expandDesk('${slot}')">Открыть чат</button>
           <button class="ghost small"
                   onclick="openExternal('${esc((slot === 'hub' || slot.startsWith('hub-')) ? deskSlotUrl(slot) : (s.agentUrl || s.url))}')">
             Ссылка</button>
           <button class="ghost small" onclick="saveSession('${slot}')">Сохранить</button>
           ${s.runId && tok() ? `<button class="ghost small" onclick="stopRun(${s.runId})">Выключить</button>` : ''}
         </div>
       </div>`;
     const chatSlots = DESK_SLOTS.filter(s => s !== 'linux' && s !== 'windows');
     box.innerHTML = `<div class="row" style="gap:10px;align-items:stretch">
       ${tile('linux', DESKS.linux, 'Linux')}
       ${tile('windows', DESKS.windows, 'Windows')}
     </div>` + chatSlots.map(s => chatRow(s, DESKS[s], KIND_LABEL[s] || s)).join('');
   }
 }

 // A gated hub plus a panel that lost the token (reinstall, another device,
 // a hand-dispatched run) used to show a bare 401 JSON. Probe first; on a 401
 // offer a relaunch (the panel then holds the token) or manual entry.
 let LAST_PROBE_NETFAIL = false;
 async function ensureHubAccess(slot) {
   const s = DESKS[slot];
   const raw = s && (s.hubUrl || s.deskUrl || s.url || '');
   const base = String(raw || '').split('#')[0].split('?')[0].replace(/\/+$/, '');
   if (!base) return true;
   let ctl = null;
   try { ctl = new AbortController(); } catch (e) {}
   let to = null;
   try {
     if (ctl) to = setTimeout(() => ctl.abort(), 8000);
     const zt = HUB_TOKENS[slot] || '';
     const r = await fetch(base + '/api/tools', zt
       ? { headers: { 'x-hub-token': zt }, signal: ctl && ctl.signal }
       : { signal: ctl && ctl.signal });
     // A dead quick tunnel often returns Cloudflare's 530 page with Error
     // 1033. Treat it as a stale session instead of opening a broken iframe;
     // the user can relaunch and receive the new ephemeral URL.
     if (r.status === 530 || r.status === 502 || r.status === 503) {
       const body = await r.text().catch(() => '');
       if (/\b1033\b|error\s*code\s*:\s*1033/i.test(body) || r.status === 530) {
         try { bootLog('проба ' + slot + ': старый Cloudflare-туннель (Error 1033)'); } catch (e2) {}
         if (confirm('Ссылка на этот туннель устарела (Cloudflare Error 1033).\n\nОК — запустить новый хаб\nОтмена — оставить сессию закрытой')) {
           await launchHub(slot === 'hub-windows' ? 'windows' : slot === 'hub-linux' ? 'linux' : undefined);
         }
         return false;
       }
     }
     if (r.status !== 401) {
       if (r.ok) {
         const identity = await r.json().catch(() => null);
         if (identity && s.runId && identity.runId && String(identity.runId) !== String(s.runId)) {
           bootLog('проба ' + slot + ': адрес отвечает другим run ' + identity.runId + ', ожидался ' + s.runId);
           if (confirm('Этот адрес обслуживает другой запуск раннера.\n\nОК — запустить правильный хаб\nОтмена — не открывать')) {
             await launchHub(slot === 'hub-windows' ? 'windows' : slot === 'hub-linux' ? 'linux' : undefined);
           }
           return false;
         }
       }
       try { bootLog('проба ' + slot + ': ' + r.status); } catch (e2) {}
       LAST_PROBE_NETFAIL = false;
       return true;
     }
   } catch (e) { try { bootLog('проба ' + slot + ': сеть недоступна — туннель/VPN?'); } catch (e2) {} LAST_PROBE_NETFAIL = true; return true; }
   finally { if (to) clearTimeout(to); }
   if (confirm('Хаб закрыт токеном, которого у панели нет (запуск с другого устройства, переустановка или ручной dispatch).\n\nОК — перезапустить хаб (панель получит новый токен)\nОтмена — ввести токен вручную')) {
     await launchHub(slot === 'hub-windows' ? 'windows' : slot === 'hub-linux' ? 'linux' : undefined);
     return false;
   }
   const manual = prompt('Токен хаба (?zt=...):', '');
   if (!manual) return false;
   HUB_TOKENS[slot] = manual.trim();
   saveHubTokens();
   return true;
 }

 async function expandDesk(slot) {
   if (slot === 'hub' || slot.startsWith('hub-')) {
     if (!await ensureHubAccess(slot)) return;
     try {
       const du = deskSlotUrl(slot);
       const dh = String(du.split('?')[0]).split('/')[2] || '';
       const dz = HUB_TOKENS[slot] || '';
       bootLog('чат ' + slot + ' · ' + dh + ' · zt ' + (dz ? 'ok (' + dz.length + ')' : 'НЕТ') + (LAST_PROBE_NETFAIL ? ' · туннель не отвечает (VPN?)' : ''));
     } catch (e) {}
   }
   deskOpen = slot; loadDesks();
 }
 function collapseDesks()  { deskOpen = null; closeDeskOverlay(); loadDesks(); }

 /** Tear down the second layer and give the page its scrolling back. */
 function closeDeskOverlay() {
   // chat-overlay is the previous generation's id; removing it too costs
   // nothing and covers a panel reloaded mid-overlay.
   for (const id of ['desk-overlay', 'chat-overlay']) {
     const ov = document.getElementById(id);
     if (ov) ov.remove();
   }
   document.body.style.overflow = '';
 }

 /** Hand the active tab's address to a real browser tab, on request. */
 // External links must never window.open() from inside the APK: with multiple
 // windows off, _blank loads in the MAIN frame and the panel loses itself
 // (tunnel hosts are "internal" for the iframe, so they stay in-view too -
 // a failed load then shows "assembly damaged"). Copy the link instead.
 async function openExternal(url) {
   url = String(url || '');
   if (!url) return;
   try {
     if (navigator.clipboard && navigator.clipboard.writeText) {
       await navigator.clipboard.writeText(url);
       alert('Ссылка скопирована — вставь её в браузере.');
       return;
     }
   } catch (e) {}
   prompt('Скопируй ссылку в браузер:', url);
 }
 function openDeskInBrowser() {
   const f = deskOpen && document.getElementById('desk-frame-' + deskOpen);
   const url = f && f.dataset.url;
   if (url) openExternal(url);
 }

 // Android's back gesture should leave the layer, not the panel. Without this
 // the overlay stays up and back appears to do nothing.
 window.addEventListener('popstate', () => {
   if (document.getElementById('desk-overlay')) collapseDesks();
 });

 const DESK_SLOTS = ['linux', 'windows', 'agent-linux', 'agent-windows', 'agent', 'opencode-linux', 'opencode-windows', 'opencode', 'hub-linux', 'hub-windows', 'hub'];

 /** Address of a slot; chat flavours go through the token query. */
 function deskSlotUrl(slot) {
   const s = DESKS[slot];
   if (!s) return '';
   if (slot === 'agent' || slot === 'opencode' || slot.startsWith('agent-') || slot.startsWith('opencode-')) return chatUrlWithQ(s.agentUrl || s.url || '');
   if (slot === 'hub' || slot.startsWith('hub-')) return hubUrlWithToken(s.hubUrl || s.deskUrl || s.url || '', slot);
   return s.hubUrl || s.deskUrl || s.url || '';
 }
 // The hub lists the account's repos from the browser (api.github.com
 // answers cross-origin); the token rides the URL fragment so it never
 // touches the hub server or its logs - fragments stay in the browser.
 // Gate tokens for panel-launched hubs, one per slot. Generated at launch,
 // passed to the run as a dispatch input (never written to the repo), kept
 // here and in localStorage so a reloaded panel still opens its hubs.
 let HUB_TOKENS = {};
 try { HUB_TOKENS = JSON.parse(localStorage.getItem('panel_hub_tokens') || '{}'); } catch (e) { HUB_TOKENS = {}; }
 function saveHubTokens() { try { localStorage.setItem('panel_hub_tokens', JSON.stringify(HUB_TOKENS)); } catch (e) {} }
 function genHubToken() {
   try { if (window.crypto && crypto.randomUUID) return crypto.randomUUID().replace(/-/g, ''); } catch (e) {}
   const h = '0123456789abcdef';
   let s = '';
   for (let i = 0; i < 32; i++) s += h[Math.floor(Math.random() * 16)];
   return s;
 }
 function hubUrlWithToken(url, slot) {
   if (!url) return url;
   let base = url.split('#')[0];
   // Idempotent: a stored URL that already carries ?zt= (saved bundle, older
   // panel) must not gain a second one - Express parses a repeated param as
   // an array, and an array never equals the token (bare 401).
   const cut = base.split('?');
   if (cut.length > 1) {
     const kept = cut[1].split('&').filter(q => q && !/^zt=/.test(q));
     base = cut[0] + (kept.length ? '?' + kept.join('&') : '');
   }
   const zt = (slot && HUB_TOKENS[slot]) || '';
   if (zt) base += (base.includes('?') ? '&' : '?') + 'zt=' + encodeURIComponent(zt);
   const t = tok();
   if (!t) return base;
   return base + '#gh=' + encodeURIComponent(t);
 }

 /**
  * Every live session as a tab in one full-screen second layer.
  *
  * It used to be one slot at a time - a chat OR a desk, and switching meant
  * closing and reopening, which reloaded the iframe and threw away what was
  * typed. Now each live slot keeps its own mounted iframe and switching tabs
  * only flips display, so a chat keeps its draft and a desk keeps streaming.
  *
  * A fixed overlay ignores the page padding and the tab bar, and 100dvh (not
  * vh) follows the browser chrome as it collapses, which is what keeps the
  * input visible when the keyboard opens on Android.
  */
 function renderDeskOverlay() {
   const live = DESK_SLOTS.filter(s => DESKS[s]);
   if (!live.includes(deskOpen)) deskOpen = live[0] || null;
   if (!deskOpen) { collapseDesks(); return; }
   let ov = document.getElementById('desk-overlay');
   if (!ov) {
     ov = document.createElement('div');
     ov.id = 'desk-overlay';
     ov.innerHTML = `
       <div style="display:flex;align-items:center;gap:6px;padding:8px 10px;
                   padding-top:calc(8px + env(safe-area-inset-top));
                   border-bottom:1px solid var(--line);background:var(--panel);
                   overflow-x:auto;flex:none">
         <div id="desk-tabs" style="display:flex;gap:6px;flex:1"></div>
         <button class="ghost small" onclick="openDeskInBrowser()">Ссылка</button>
         <button class="ghost small" id="desk-save-btn">Сохранить</button>
         <button class="ghost small" onclick="collapseDesks()">Закрыть</button>
       </div>
       <div id="desk-frames" style="flex:1;display:flex;min-height:0"></div>`;
     document.body.appendChild(ov);
   }
   ov.style.cssText =
     'position:fixed;inset:0;z-index:9999;background:var(--bg);' +
     'display:flex;flex-direction:column;height:100dvh';
   document.body.style.overflow = 'hidden';
   syncDeskOverlay();
 }

 /**
  * Reconcile the layer with fresh DESKS: rebuild the tab bar (cheap, no
  * iframes inside it), create frames for newly live slots, drop dead ones,
  * show the active tab. A frame whose address did not change is never
  * touched - that is the whole point.
  */
 function syncDeskOverlay() {
   const ov = document.getElementById('desk-overlay');
   if (!ov) return;
   const live = DESK_SLOTS.filter(s => DESKS[s]);
   if (!live.length) { collapseDesks(); return; }
   if (!live.includes(deskOpen)) deskOpen = live[0];
   const bar = document.getElementById('desk-tabs');
   if (bar) {
     bar.innerHTML = live.map(s =>
       `<button class="${s === deskOpen ? 'small' : 'ghost small'}" ` +
       `onclick="switchDeskTab('${s}')">${esc(KIND_LABEL[s] || s)}</button>`
     ).join('');
   }
   const saveBtn = document.getElementById('desk-save-btn');
   if (saveBtn) saveBtn.setAttribute('onclick', `saveSession('${deskOpen}')`);
   const wrap = document.getElementById('desk-frames');
   if (!wrap) return;
   for (const s of live) {
     const url = deskSlotUrl(s);
     let f = document.getElementById('desk-frame-' + s);
     if (!f) {
       f = document.createElement('iframe');
       f.id = 'desk-frame-' + s;
       f.style.cssText = 'border:0;flex:1;width:100%;height:100%;background:#000';
       f.setAttribute('allow', 'clipboard-read; clipboard-write');
       f.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-popups');
       wrap.appendChild(f);
     }
     if (url && f.dataset.url !== url) { f.dataset.url = url; f.src = url; }
     f.style.display = s === deskOpen ? 'block' : 'none';
   }
   for (const s of DESK_SLOTS) {
     if (!DESKS[s]) {
       const f = document.getElementById('desk-frame-' + s);
       if (f) f.remove();
     }
   }
 }

 function switchDeskTab(slot) { deskOpen = slot; syncDeskOverlay(); }

 /**
  * Save this minute's { session, models } bundle to the session-state branch
  * as saved/<slot>-<UTC timestamp>.json - the manual half of the transfer
  * (the automatic half runs in the workflows at shutdown). Timestamped, so it
  * never overwrites: the branch keeps history, not just the latest.
  */
 async function saveSession(slot) {
   if (!tok()) { alert('Нужен токен, чтобы сохранять.'); return; }
   const s = DESKS[slot];
   if (!s) { alert('Сессия уже закрыта — сохранять нечего.'); return; }
   const d = new Date();
   const p2 = n => String(n).padStart(2, '0');
   const ts = `${d.getUTCFullYear()}${p2(d.getUTCMonth() + 1)}${p2(d.getUTCDate())}` +
     `T${p2(d.getUTCHours())}${p2(d.getUTCMinutes())}${p2(d.getUTCSeconds())}`;
   const bundle = { savedAt: d.toISOString(), slot, session: s, models: MODELS[slot] || null };
   const content = btoa(unescape(encodeURIComponent(JSON.stringify(bundle, null, 2))));
   // The history is filed by day and weekday, so "what was running last Friday"
   // is one directory listing away.
   const day = `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}`;
   const weekday = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][d.getUTCDay()];
   const path = `history/${day}/${weekday}/saved-${slot}-${ts}.json`;
   try {
     await api(`${CTL()}/contents/${path}`, {
       method: 'PUT',
       headers: Object.assign(hdr(), { 'Content-Type': 'application/json' }),
       body: JSON.stringify({ message: `save ${slot} ${ts}`, content, branch: 'session-state' })
     });
     alert('Сохранено: ' + path);
   } catch (e) {
     alert('Не вышло: ' + e.message);
   }
 }

 /**
  * Open a desk or the chat inside the panel, from anywhere in the UI.
  *
  * The desks card sits on the session page, so a button elsewhere has to switch
  * to that page first and then scroll to it - expanding something the user
  * cannot see reads as a dead button. loadDesks() is async, hence the scroll on
  * the next frame, once the iframe has been laid out.
  */
 /** Newest live slot of a family: 'agent' -> 'agent-linux' if that run is up. */
 function liveSlotOf(fam) {
   return DESK_SLOTS.find(s => (s === fam || s.startsWith(fam + '-')) && DESKS[s]) || fam;
 }

 function openDeskInPanel(slot) {
   go('sess');
   expandDesk(slot);
   requestAnimationFrame(() => {
     const el = $('desks');
     if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
   });
 }

 // ── one session per account ─────────────────────────────────────────
 //
 // Three workflows and four modes were three too many decisions to make before
 // getting a screen. There is one session at a time now, and what it is decides
 // what opens: Windows means RDP, Linux means a desktop and a terminal, the
 // agent means its own hub. Free ngrok allows one tunnel anyway, so a second
 // concurrent session could never have been reachable - the old panel let you
 // start one regardless and then showed a blank page.

 const KIND_LABEL = { linux: 'Linux', windows: 'Windows', agent: 'CLI-агент', 'agent-linux': 'CLI-агент Linux', 'agent-windows': 'CLI-агент Windows', opencode: 'OpenCode', 'opencode-linux': 'OpenCode Linux', 'opencode-windows': 'OpenCode Windows', hub: 'NPM-Hub', 'hub-linux': 'NPM-Hub Linux', 'hub-windows': 'NPM-Hub Windows' };

 function busyButtons(on, which) {
   for (const id of ['btn-windows', 'btn-agent', 'btn-opencode', 'btn-hub']) {
     const b = $(id); if (!b) continue;
     b.disabled = on;
   }
   const b = $(which); if (b) b.textContent = on ? 'Запускаю…' : (b.dataset.label || b.textContent);
 }

 // Chat sessions only. Desks use a different tunnel and can stay up.
 function anyLive(runs) {
   return runs.filter(r => ['Zen agent', 'Remote session', 'OpenCode', 'opencode', 'Desks', 'NPM Hub'].includes(r.name)
                           && r.status !== 'completed');
 }
 const ACTIVE_RUN_STATUSES = ['queued', 'requested', 'waiting', 'in_progress', 'pending'];
 async function runStatus(id, repo) {
   try { return await api(`${GH}/repos/${repo || ctlRepo()}/actions/runs/${id}`); }
   catch (e) { if (/^404:/.test(e.message)) return null; throw e; }
 }
 async function waitForRunsToStop(ids, repo, attempts, pauseMs) {
   const pending = new Set((ids || []).map(String));
   const limit = attempts == null ? 400 : attempts;
   const pause = pauseMs == null ? 2500 : pauseMs;
   for (let i = 0; pending.size && i < limit; i++) {
     await new Promise(r => setTimeout(r, pause));
     for (const id of Array.from(pending)) {
       const run = await runStatus(id, repo);
       if (!run || !ACTIVE_RUN_STATUSES.includes(run.status)) pending.delete(id);
     }
   }
   if (pending.size) throw new Error('GitHub ещё не остановил старый запуск. Повторите запуск позже.');
   return true;
 }
 async function cancelRunsAndWait(runs, repo) {
   const ids = [];
   for (const run of runs) {
     if (!await cancelRun(run.id, repo)) throw new Error('GitHub не принял остановку старого запуска.');
     ids.push(run.id);
   }
   if (ids.length) await waitForRunsToStop(ids, repo);
   return ids.length;
 }
 function foreignSession(runs, own) {
   const ids = new Set((own || []).map(r => String(r.id)));
   return anyLive(runs).find(r => !ids.has(String(r.id))) || null;
 }

 let PENDING_Q = '';
 function readFirstCommand() {
   const el = $('first-cmd');
   PENDING_Q = (el && el.value.trim()) || '';
   return PENDING_Q;
 }
 function chatUrlWithQ(url) {
   if (!PENDING_Q || !url) return url;
   if (/[?&]q=/.test(url)) return url;
   return url + (url.includes('?') ? '&' : '?') + 'q=' + encodeURIComponent(PENDING_Q);
 }

 // ── start the desks ─────────────────────────────────────────────────
 //
 // The Desks workflow runs a single Windows desk; agent/hub/opencode runs are
 // untouched by this button.
 async function launchDesks() {
   if (!tok()) { alert('Сначала добавьте аккаунт на вкладке «Аккаунт».'); return; }

   const runs = await currentRuns();
   const already = runs.filter(r => r.name === 'Desks' && r.status !== 'completed');
   const other = foreignSession(runs, already);
   if (other) {
     alert('Другая сессия уже использует раннер. Остановите её перед запуском стола.');
     return;
   }
   let stoppedOld = false;
   if (already.length) {
     if (!confirm(`Стол уже поднят (${mins(already[0].created_at)} мин).\n\n` +
                  'ОК — остановить и поднять заново.\nОтмена — оставить как есть.')) {
       await refresh(); return;
     }
     try { await cancelRunsAndWait(already); stoppedOld = true; }
     catch (e) { alert('Не вышло: ' + e.message); return; }
   }

   const btn = $('btn-windows');
   btn.dataset.label = btn.dataset.label || btn.textContent;
   for (const b of ['btn-windows']) {
     if ($(b)) $(b).disabled = true;
   }
   btn.textContent = 'Поднимаю…';
   try {
     const launchSince = Date.now();
     const ri = runnerInputs();
     const r = await dispatchWorkflow('desks.yml', {
       label: (acct() && acct().login) || 'desks',
       runner_windows: ri.runner_windows
     });
     if (r.status !== 204) throw new Error(r.status + ' ' + (await r.text()).slice(0, 200));

     // A desk takes two to four minutes to install, tunnel and publish. Poll
     // rather than promising it is ready: the tile appears the moment the
     // address lands in the session-state branch.
     const wantDesks = ['windows'];
     for (let i = 0; i < 90; i++) {
       await new Promise(res => setTimeout(res, 5000));
       let hit = null;
       for (const dslot of wantDesks) {
         try { hit = await readSessionSlot(dslot); }
         catch (e) {
           if (e && e.is403) {
             sessPausedUntil = Date.now() + (e.unbanMs || 600000);
             alert('GitHub ограничил запросы (403). Адрес появится в «Доступах» позже.');
             return;
           }
         }
         if (hit) break;
       }
       if (hit) {
         const born = Date.parse(hit.startedAt || '');
         if (Number.isFinite(born) && born >= launchSince - 15000) break;
         hit = null;
       }
       btn.textContent = `Поднимаю… ${Math.round(i * 5 / 60 * 10) / 10} мин`;
     }
     await refresh();
   } catch (e) {
     // See launchAgent: the old desk was stopped by hand, so a failed dispatch
     // leaves nothing running. Say that, instead of only the status code.
     alert('Не вышло: ' + e.message + (stoppedOld
       ? '\n\nПрежний запуск уже остановлен, активной сессии сейчас нет. Нажмите кнопку ещё раз.'
       : ''));
   } finally {
     for (const b of ['btn-windows']) {
       if ($(b)) { $(b).disabled = false; $(b).textContent = $(b).dataset.label || $(b).textContent; }
     }
   }
 }

