 async function waitAndOpen(kind, sinceMs = Date.now()) {
   BOOT_SEEN = new Set();
   if ($('boot-log')) $('boot-log').innerHTML = '';
   bootLog('отправка workflow…');
   try { if (window.ZenBridge && ZenBridge.requestNotifications) ZenBridge.requestNotifications(); } catch (e) {}
   // kind is the slot ('agent-linux'); the family drives buttons and budgets.
   const fam = kind === 'linux' || kind === 'windows' ? kind
     : kind.startsWith('agent-') ? 'agent'
     : kind.startsWith('opencode-') ? 'opencode'
     : kind.startsWith('hub-') ? 'hub' : kind;
   const btnId = fam === 'windows' ? 'btn-windows'
     : fam === 'agent' ? 'btn-agent'
     : fam === 'opencode' ? 'btn-opencode'
     : fam === 'hub' ? 'btn-hub'
     : 'btn-windows';
   const btn = $(btnId);
   const budget = fam === 'windows' || fam === 'opencode' || fam === 'hub' ? 90 : 70;
   const wantName = fam === 'agent' ? 'Zen agent'
     : fam === 'opencode' ? 'OpenCode'
     : fam === 'hub' ? 'NPM Hub'
     : 'Desks';
   let lastStep = '';
   for (let i = 0; i < budget; i++) {
     const sec = i * 5;
     if (btn) btn.textContent = `Поднимаю… ${sec}s`;
     if (i === 0) await new Promise(r => setTimeout(r, 1200));
     else await new Promise(r => setTimeout(r, 5000));
     // Session file first — cheap and is what we actually need. One slot
     // only: fetching all seven every few seconds is what trips GitHub's
     // abuse throttle (~9 calls per tick before, ~3 now).
     let s = null;
     try {
       s = await readSessionSlot(kind);
     } catch (e) {
       if (e && e.is403) {
         bootLog('GitHub ограничил запросы — жду, не стучу.');
         if (btn) btn.textContent = 'Пауза (403)';
         alert('GitHub ограничил запросы (403). Подождите минуту и обновите «Доступы» вручную.');
         return;
       }
     }
     const born = s && Date.parse(s.startedAt || '');
     if (s && (!Number.isFinite(born) || born < sinceMs - 15000)) s = null;
     const ready = s && (s.agentUrl || s.deskUrl || s.rdpHost ||
       (fam !== 'agent' && fam !== 'opencode' && s.url));
     if (ready) {
       await refresh();
       sessionReady(kind, s);
       return;
     }
     // Job steps only while waiting, not on a background timer.
     try {
       const runs = (await api(`${CTL()}/actions/runs?per_page=8`)).workflow_runs || [];
       const r = runs.find(x => x.name === wantName && x.status !== 'completed')
         || runs.find(x => x.status !== 'completed');
       if (r) {
         if (r.status === 'queued') bootLog('в очереди GitHub Actions');
         else if (r.status === 'in_progress') bootLog('раннер взят · #' + r.run_number);
         const jobs = (await api(`${CTL()}/actions/runs/${r.id}/jobs`)).jobs || [];
         for (const j of jobs) {
           const cur = (j.steps || []).find(st => st.status === 'in_progress');
           const name = cur ? cur.name : (j.status === 'queued' ? 'ожидание раннера' : '');
           if (name && name !== lastStep) {
             lastStep = name;
             const took = cur && cur.started_at
               ? Math.round((Date.now() - new Date(cur.started_at).getTime()) / 1000) : 0;
             bootLog(name + (took ? ' · ' + took + ' с' : ''));
           }
         }
       }
     } catch (e) {
       // Anything but a ban is worth waiting through; a ban is not.
       if (e && e.is403) {
         bootLog('GitHub ограничил запросы — жду, не стучу.');
         if (btn) btn.textContent = 'Пауза (403)';
         return;
       }
     }
   }
   await refresh();
   bootLog('таймаут ожидания адреса — смотрите «Доступы»');
   alert('Сессия ещё поднимается. Адрес появится в «Доступах» через минуту.');
 }

 // Open whatever the live session is, in the way that suits it.
 function openLive() {
   const s = LIVE;
   if (!s) {
     // The run list and the published address come from different places: a
     // session can be running for a minute before it has an address, and an
     // entry left by an earlier run can be stale. Saying "no active session"
     // while two are visibly running - which is what the panel did - is the
     // least useful answer available.
     alert(LAST_RUNS && LAST_RUNS.length
       ? 'Сессия запущена, но ещё не сообщила адрес.\n\n' +
         'Обычно это первые 1–2 минуты. Если висит дольше — откройте журнал: ' +
         'возможно, туннель занят другой сессией.'
       : 'Активной сессии нет.');
     return;
   }
   // Both of these used to be window.open(), which on a phone leaves the app
   // and hands the session token to the browser's address bar and history.
   // They open in the panel now; "В браузере" is still there for anyone who
   // wants a real tab.
   //
   // The desks card lives on the session page - there is no separate "desks"
   // tab - and openDeskInPanel() scrolls to it, because expanding a panel that
   // is off-screen looks like the button did nothing.
   if (s.agentUrl) {
     openDeskInPanel(liveSlotOf(String(s._slot || '').startsWith('opencode') || /opencode/i.test(s.kind || '') ? 'opencode' : 'agent'));
     return;
   }
   if (String(s._slot || '').startsWith('hub') || s.hubUrl || /npm-hub/i.test(s.kind || '')) {
     openDeskInPanel(liveSlotOf('hub'));
     return;
   }
   if (s.rdpHost) {
     // RDP is not HTTP: there is nothing to open in a browser, so hand over the
     // details and let the RDP client take them.
     alert('Windows: откройте Microsoft Remote Desktop и добавьте ПК\n\n' +
           'Адрес: ' + s.rdpHost + '\nЛогин: ' + (s.rdpUser || 'zenrdp') +
           '\nПароль: ' + (s.rdpPass || '—') +
           '\n\nЭти же поля с кнопкой «копия» — ниже в «Доступах».');
     go('sess');
     return;
   }
   alert('Сессия ещё не сообщила адрес.');
 }

 async function cancelRun(id, repo) {
   const r = await fetch(`${GH}/repos/${repo || ctlRepo()}/actions/runs/${id}/cancel`,
     { method: 'POST', headers: hdr() });
   // 202 accepted; 409 means it had already finished, which is fine here.
   return r.status === 202 || r.status === 409;
 }

 async function stopRun(id, repo) {
   if (!tok()) { alert('Нужен токен, чтобы останавливать.'); return; }
   if (!confirm('Остановить сессию? Автосейв уже отправил работу в ветку.')) return;
   const ok = await cancelRun(id, repo);
   if (ok) await markSessionEnded(id);
   alert(ok ? 'Остановлено. Раннер сворачивается ~полминуты.' : 'Не вышло.');
   setTimeout(() => { refresh(); if (page === 'act') loadActions(true); }, 4000);
 }

 // Rerun keeps the same inputs and the same gate token: cancel the live run,
 // wait for GitHub to mark it finished, then rerun the finished run.
 async function rerunRun(id, repo) {
   if (!tok()) { alert('Нужен токен, чтобы перезапускать.'); return; }
   repo = repo || ctlRepo();
   let d;
   try { d = await api(`${GH}/repos/${repo}/actions/runs/${id}`); }
   catch (e) { d = { status: 'error' }; }
   if (d.status === 'in_progress' || d.status === 'queued' || d.status === 'pending' || d.status === 'waiting') {
     const c = await fetch(`${GH}/repos/${repo}/actions/runs/${id}/cancel`,
       { method: 'POST', headers: hdr() });
     if (c.status !== 202 && c.status !== 409) { alert('Не вышло отменить текущий запуск.'); return; }
     alert('Отменяю текущий запуск — перезапуск стартует, когда GitHub его закроет.');
     for (let i = 0; i < 24; i++) {
       await new Promise(r => setTimeout(r, 2500));
       try { d = await api(`${GH}/repos/${repo}/actions/runs/${id}`); } catch (e) { break; }
       if (d.status === 'completed' || d.status === 'cancelled') break;
     }
   }
   if (!(d.status === 'completed' || d.status === 'cancelled' || d.status === 'success'
       || d.status === 'failure')) {
     alert('Запуск ещё не завершился — перезапуск станет доступен позже.');
     return;
   }
   const r = await fetch(`${GH}/repos/${repo}/actions/runs/${id}/rerun`,
     { method: 'POST', headers: hdr() });
   if (r.status === 201) alert('Перезапуск принят — те же входные данные и токен сессии.');
   else alert('Не вышло: ' + r.status + ' ' + (await r.text()).slice(0, 200));
   setTimeout(() => { refresh(); if (page === 'act') loadActions(true); }, 3000);
 }

