       : '<div class="ico">▦</div>'}
     <div class="grow">
       <div class="name">${esc(a.label)}</div>
       <div class="meta">${esc(a.pkg || '')}</div>
     </div>
   </div>`).join('');
 }
 // The list is filtered on every keystroke, so a tap has to find the app in the
 // filtered view rather than in the original array.
 function appsOpen(i) {
   const a = appsFilter()[i];
   if (!a || !a.pkg) return;
   try {
     ZenBridge.launchApp(a.pkg);
   } catch (e) {
     alert('Не открылось: ' + (e.message || e));
   }
 }

 async function loadPanelApk() {
   const box = $('apk-panel');
   await loadInstalledVersion();
   renderUpdateBanner();
   try {
     const rel = await latestRelease();
     const file = releaseFile(rel);
     const remote = releaseCode(rel);
     const mine = parseInt(INSTALLED.versionCode, 10) || 0;
     const newer = remote > mine && mine > 0;
     if (!rel || !file) {
       const d = await api(`${CTL()}/actions/runs?per_page=20`);
       const b = (d.workflow_runs || []).find(r =>
         (r.name === 'Panel APK' || r.name === 'Build Zen Panel APK' ||
          r.name === 'Build Zen Panel Desktop') && r.conclusion === 'success');
       box.innerHTML = b
         ? `<table><tr><td>Сборка</td><td>#${b.run_number} · ${ago(b.updated_at)}</td></tr>
            <tr><td>Скачать</td><td><a href="#" onclick="openExternal(\'${esc(b.html_url)}\');return false">артефакт запуска</a></td></tr></table>`
         : (wantDesktopRelease()
           ? '<span class="note">релиза ещё нет — соберите его workflow «Build Zen Panel Desktop»</span>'
           : '<span class="note">релиза ещё нет — нажмите «Собрать и выпустить APK»</span>');
       return;
     }
     box.innerHTML = `<table>
       <tr><td>Релиз</td><td><b>${esc(rel.name || rel.tag_name)}</b> · ${ago(rel.published_at || rel.created_at)}</td></tr>
       <tr><td>У вас</td><td>${mine ? esc(INSTALLED.versionName || String(mine)) : (wantDesktopRelease() ? 'dev-сборка' : 'не APK / веб')}</td></tr>
       <tr><td>Файл</td><td>${esc(file.name)} · ${kb(file.size)}</td></tr>
     </table>
     <div class="row" style="margin-top:10px">
       <a href="${esc(file.browser_download_url)}"><button>${newer ? 'Обновить ' + downloadWord() : 'Скачать ' + downloadWord()}</button></a>
       <button class="ghost" onclick="openExternal('${esc(rel.html_url)}')">Страница релиза</button>
     </div>
     ${newer ? '<div class="warn">Доступна более новая версия. Скачайте и установите поверх текущей.</div>' : ''}`;
   } catch (e) {
     box.innerHTML = `<div class="danger">${esc(e.message)}</div>`;
   }
 }

 function renderUpdateBanner() {
   const sub = $('subtitle');
   if (sub) sub.textContent = INSTALLED.versionName
     ? ('панель · ' + INSTALLED.versionName)
     : 'панель управления';
 }

 async function checkUpdateBanner() {
   await loadInstalledVersion();
   renderUpdateBanner();
   const mine = parseInt(INSTALLED.versionCode, 10) || 0;
   if (!mine) return;
   try {
     const rel = await latestRelease();
     const file = releaseFile(rel);
     const remote = releaseCode(rel);
     if (!file || remote <= mine || document.getElementById('upd-banner')) return;
     const bar = document.createElement('div');
     bar.id = 'upd-banner';
     bar.className = 'warn';
     bar.innerHTML = 'Доступно обновление <b>' + esc(rel.tag_name || rel.name) +
       '</b> · <a href="' + esc(file.browser_download_url) + '">скачать обновление</a>';
     document.body.insertBefore(bar, document.body.firstChild);
   } catch (e) {}
 }

 // ── shared bits ─────────────────────────────────────────────────────
 function pill(r) {
   if (runIsQueued(r))              return '<span class="pill idle">в очереди</span>';
   if (r.status !== 'completed')     return '<span class="pill run">идёт</span>';
   if (r.conclusion === 'success')   return '<span class="pill ok">успех</span>';
   if (r.conclusion === 'cancelled') return '<span class="pill idle">отменён</span>';
   return '<span class="pill bad">ошибка</span>';
 }
 const mins = iso => Math.round((Date.now() - new Date(iso)) / 60000);
 function ago(iso) {
   const m = mins(iso);
   if (m < 60) return m + ' мин назад';
   if (m < 1440) return Math.round(m / 60) + ' ч назад';
   return Math.round(m / 1440) + ' дн назад';
 }
 const kb = n => n >= 1048576 ? (n / 1048576).toFixed(1) + ' МБ'
              : n >= 1024 ? Math.round(n / 1024) + ' КБ' : n + ' Б';

 // ── ЖУРНАЛ ЗАПУСКОВ: по дням, по дням недели, удачно или нет ──────────
 // Runs used to be a flat list on the Actions tab and nothing else. Here they
 // are what they actually are: a diary of sessions, grouped by the day they
 // started and by the weekday, with the outcome spelled out. Built from the
 // runs the page already polls, so it costs no extra requests.
 const SESSION_RUN_NAMES = new Set(['NPM Hub', 'Zen agent', 'OpenCode', 'Desks']);
 // Indexed by Date#getDay(), so Sunday is 0 - the same shape as history/<Wd>/.
 const WD_SHORT = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];
 const MONTHS = ['января','февраля','марта','апреля','мая','июня','июля','августа',
                 'сентября','октября','ноября','декабря'];
 const runKind = r => (r.name === 'Zen agent' ? 'CLI-агент'
   : (r.name === 'OpenCode' || r.name === 'opencode') ? 'OpenCode'
   : r.name === 'Desks' ? 'Столы' : r.name === 'NPM Hub' ? 'NPM-Hub' : r.name);
 function runOutcome(r) {
   if (r.conclusion === 'success')   return { cls: 'ok', text: 'успех' };
   if (r.conclusion === 'cancelled') return { cls: 'idle', text: 'отменён' };
   if (r.conclusion === 'skipped')   return { cls: 'idle', text: 'пропущен' };
   return { cls: 'bad', text: 'ошибка' };
 }
 function renderRunJournal(runs) {
   const box = $('journal');
   if (!box) return;
   const done = runs
     .filter(r => SESSION_RUN_NAMES.has(r.name) && r.status === 'completed')
     .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
     .slice(0, 80);
   if (!done.length) { box.innerHTML = '<span class="note">журнал пуст</span>'; return; }
   const byDay = new Map();
   for (const r of done) {
     const d = new Date(r.created_at);
     const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
     if (!byDay.has(key)) byDay.set(key, []);
     byDay.get(key).push({ r, d });
   }
   const today = new Date();
   const parts = [];
   for (const [day, items] of byDay) {
     const ok = items.filter(x => x.r.conclusion === 'success').length;
     const bad = items.length - ok;
     const isToday = day === `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
     const wd = WD_SHORT[items[0].d.getDay()] || '';
     const title = isToday ? 'сегодня' : `${items[0].d.getDate()} ${MONTHS[items[0].d.getMonth()]}`;
     parts.push(`<div style="margin:10px 0 4px;font-weight:700;font-size:12px">${esc(title)} · ${esc(wd)}`
       + ` <span class="note">${items.length} запуск(ов)`
       + (ok ? ` · <span class="ok">${ok} успех</span>` : '')
       + (bad ? ` · <span class="danger">${bad} неудач</span>` : '')
       + `</span></div>`);
     parts.push('<table>' + items.map(({ r, d }) => {
       const o = runOutcome(r);
       const t = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
       return `<tr><td>${t}</td><td>#${r.run_number}</td>
         <td>${esc(runKind(r))} <span class="pill ${o.cls}">${o.text}</span></td>
         <td><a href="#" onclick="openExternal('${esc(r.html_url)}');return false">журнал</a></td></tr>`;
     }).join('') + '</table>');
   }
   box.innerHTML = parts.join('');
 }

 async function refresh() {
   let runs = [];
   try { runs = (await api(`${CTL()}/actions/runs?per_page=100`)).workflow_runs || []; }
   catch (e) {
     $('live').innerHTML = `<div class="danger">${esc(e.message)}</div>`;
     if (e && e.is403) sessPausedUntil = Date.now() + (e.unbanMs || 600000);
     return;
   }
   handoffPanelPoll();

   const live = anyLive(runs);
   LAST_RUNS = live;
   const conflict = $('agent-conflict');
   if (live.length > 1) {
     // Should not happen now that launching stops what is running, but an old
     // session started before this change can still collide - and the free plan
     // gives one tunnel, so the extra one is simply unreachable.
     conflict.style.display = '';
     conflict.innerHTML = 'Запущено несколько сессий. Туннель достанется первой, ' +
       'остальные недоступны — лишние стоит выключить.';
   } else conflict.style.display = 'none';

   $('live').innerHTML = live.length
     ? '<table>' + live.map(r => {
         const used = mins(r.created_at), left = Math.max(0, 360 - used);
         const kind = r.name === 'Zen agent' ? 'CLI-агент'
           : (r.name === 'OpenCode' || r.name === 'opencode') ? 'OpenCode'
           : r.name === 'Desks' ? 'Столы'
           : 'Рабочий стол';
         const started = new Date(r.created_at).getTime();
         const ageText = runIsQueued(r) ? `в очереди · создана ${used} мин назад` : `идёт ${used} мин · осталось ~${left} мин`;
         return `<tr><td>#${r.run_number}</td>
           <td><b>${esc(kind)}</b> ${pill(r)}
             <div class="note"><span class="live-age" data-started="${started}" data-queued="${runIsQueued(r) ? '1' : '0'}">${ageText}</span> ·
               <a href="#" onclick="openExternal(\'${esc(r.html_url)}\');return false">журнал</a></div>
             <button class="small" onclick="${kind === 'CLI-агент' ? "openDeskInPanel(liveSlotOf('agent'))" : kind === 'OpenCode' ? "openDeskInPanel(liveSlotOf('opencode'))" : 'openLive()'}">Открыть чат</button>
             <button class="ghost small" onclick="stopRun(${r.id})">Выключить</button></td>
           </tr>`;
       }).join('') + '</table>'
     : '<span class="note">сессия не запущена</span>';

   renderRunJournal(runs);

   // Awaited: the credentials decide what the screen and access cards show, and
   // firing this off unawaited left refresh() reporting a live session above two
   // cards that were still empty.
   try { await loadDesks(); await loadCreds(); }
   catch (e) { if (e && e.is403) sessPausedUntil = Date.now() + (e.unbanMs || 600000); }

   if (page !== 'apk') return;
   const build = runs.find(r => r.name === 'Build APK' && r.conclusion === 'success');
   const box = $('apk');
   if (!box) return;
   if (!build) { box.innerHTML = '<span class="note">успешных сборок пока нет</span>'; return; }
   try {
     const a = await api(`${CTL()}/actions/runs/${build.id}/artifacts`);
     const arts = a.artifacts || [];
     box.innerHTML = `<table>
       <tr><td>Сборка</td><td>#${build.run_number} · ${ago(build.updated_at)}</td></tr>
       <tr><td>Артефакт</td><td>${arts.length
         ? (arts[0].size_in_bytes / 1048576).toFixed(1) + ' МБ (сжатый)' : 'истёк'}</td></tr>
       <tr><td>Ссылка</td><td><a href="#" onclick="openExternal(\'${esc(build.html_url)}\');return false">сводка —
         там gofile и MD5</a></td></tr></table>`;
   } catch (e) {
     box.innerHTML = '<span class="note">не удалось прочитать артефакты</span>';
   }
 }

 function tickAges() {
   if (document.hidden) return;
   const any = document.querySelector('.live-age[data-started]');
   if (!any) return;
   document.querySelectorAll('.live-age[data-started]').forEach(el => {
     const used = Math.max(0, Math.round((Date.now() - Number(el.dataset.started)) / 60000));
     el.textContent = el.dataset.queued === '1'
       ? 'в очереди · создана ' + used + ' мин назад'
       : 'идёт ' + used + ' мин · осталось ~' + Math.max(0, 360 - used) + ' мин';
   });
 }

 $('act-repo').textContent = ACT_REPO;
 go('sess');
 loadAccount();
 startWatching();
 checkUpdateBanner();
 setInterval(tickAges, 1000);
 // Session tab: session-state + run list. 12s is enough to feel live without
 // stacking GitHub calls the way a 5s jobs poll did.
 setInterval(() => { if (page === 'sess' && !document.hidden && Date.now() >= sessPausedUntil) refresh(); }, 12000);
 // Эстафета: статус и лимиты лежат в репозитории, поэтому карточка обновляется
 // сама — и работает, даже когда хаб уже переехал на новый раннер.
 setInterval(() => { if (typeof handoffPanelPoll === 'function') handoffPanelPoll(); }, 15000);
 // Back on screen: catch up immediately instead of waiting for the next tick,
 // and replay anything the offline queue promised to send.
 document.addEventListener('visibilitychange', () => {
   if (document.hidden) return;
   if (typeof PanelOffline === 'object' && PanelOffline.flush) PanelOffline.flush();
   if (page === 'sess' && Date.now() >= sessPausedUntil) refresh();
   else if (page === 'act' && typeof pollWatch === 'function' && !watchPaused) pollWatch();
 });
 </script>
 </body>
 </html>

