 }
 function termDismissModal() {
   const t = activeTab;
   if (!t || !t.ws || t.ws.readyState !== 1) return;
   if (Date.now() - __termDismissedAt < 10000) return;
   __termDismissedAt = Date.now();
   // Esc закрывает полноэкранную модалку opencode, Enter гасит промах/промпт.
