       tab.lastPong = Date.now();
       tab.retry = 0;
       tab.disconnected = false;
       hideCountdown(id);
       if (activeTab?.id === id) fitTerm(tab);
       socket.send(JSON.stringify({ type: 'open', toolId: isPlain ? '_terminal' : effectiveToolId, sessionId: id, cwd,
         repoPath: (resume && resume.repoPath) || null, emulator: (resume && resume.emulator) || null,
         phoneRunner: (resume && resume.phoneRunner) || null, cols: term.cols, rows: term.rows }));
       if (!isTouch) term.focus();
     };

     socket.onmessage = (e) => {
       let m;
       try { m = JSON.parse(e.data); } catch { return; }
       if (m.type === 'pong') { tab.lastPong = Date.now(); return; }
       if (m.type === 'output' && m.id === id) { term.write(m.data); }
       if (m.type === 'exit') {
         term.write(`\r\n\x1b[33m[Exited ${m.code} — нажми ⟲, чтобы перезапустить]\x1b[0m\r\n`);
         termRecoverShow('⚠ Сессия завершилась — перезапустите агента');
         renderSidebar();
       }
       if (m.type === 'error') term.write(`\r\n\x1b[31m[Error: ${m.error}]\x1b[0m\r\n`);
