   // Pings are throttled by Chrome in background — therefore we also fire
   // one immediately when the page becomes visible again (wake-up call).
   let keepaliveIdle = 0;
   tab.keepAlive = setInterval(() => {
     if (tab.manualClose || !tab.socket) return;
