     tab.reconnectTimer = setTimeout(() => {}, 0); // чистим таймер реконнекта
     keepaliveIdle = 0;
   }
 });

   term.onData((data) => {
     termSendInput(tab.socket, data);
   });

   term.onResize(({ cols, rows }) => {
     // Дегенеративный размер (fit нулевой/скрытой ширины) в tmux не шлём:
     // раньше он реально сужал сессию до узкой щели, которая так в ней
     // и оставалась после восстановления связи.
     if (cols < 20 || rows < 3) return;
     if (tab.socket && tab.socket.readyState === WebSocket.OPEN) tab.socket.send(JSON.stringify({ type: 'resize', cols, rows }));
   });

   tab.resizeObs = new ResizeObserver(() => { if (activeTab?.id === id) fitTerm(tab); });
   tab.resizeObs.observe(panel);

   switchTab(id);
 }

 function renderTabs() {
   document.getElementById('tabs').innerHTML = tabs.map(t => `
     <div class="tab ${activeTab?.id === t.id ? 'on' : ''}" onclick="switchTab('${t.id}')">
       <span class="tab-dot" style="background:${t.toolColor}"></span>
       <span>${t.toolIcon} ${t.toolName}</span>
       <span class="tab-x" onclick="event.stopPropagation();closeTab('${t.id}')">✕</span>
     </div>
   `).join('') + `<div class="tab-add" onclick="showNewTermModal()">+</div>`;
 }

 function fitTerm(tab) {
   if (!tab || !tab.fitAddon || !tab.term) return;
   const panel = document.getElementById('panel-' + tab.id);
   if (panel && panel.offsetParent === null) return; // скрыта — fit сожмёт в щелочку
   tab.fitAddon.fit();
 }

 function switchTab(id) {
   activeTab = tabs.find(t => t.id === id);
   document.querySelectorAll('.tab').forEach((el, i) => el.classList.toggle('on', tabs[i]?.id === id));
   document.querySelectorAll('.term-panel').forEach(p => p.classList.remove('on'));
   const panel = document.getElementById('panel-' + id);
   if (panel) panel.classList.add('on');
   if (activeTab) setTimeout(() => {
     fitTerm(activeTab);
     if (!isTouch) activeTab.term?.focus();
     activeTab.scroll?.upd?.();
   }, 50);
   renderSidebar();
 }

 function closeTab(id) {
   const idx = tabs.findIndex(t => t.id === id);
   if (idx === -1) return;
   const t = tabs[idx];
   t.manualClose = true;
   // Closing a tab must end the server-side session, not just detach: a leftover
   // tmux session is re-attached on the next page load (/api/sessions), so closed
   // tabs came back and kept piling up. 'kill' terminates it for good.
   try { if (t.socket && t.socket.readyState === 1) t.socket.send(JSON.stringify({ type: 'kill' })); } catch {}
   // HTTP fallback: the tab may be mid-reconnect, when a WS frame cannot be sent.
   try { fetch('/api/sessions/' + encodeURIComponent(id) + '/kill', { method: 'POST' }).catch(() => {}); } catch {}
   if (t.keepAlive) clearInterval(t.keepAlive);
   if (t.cdTimer) clearInterval(t.cdTimer);
   if (t.resizeObs) t.resizeObs.disconnect();
   if (t.scroll?.destroy) t.scroll.destroy();
   if (t.touchHandler?.destroy) t.touchHandler.destroy();
   t.socket?.close();
   t.term?.dispose();
   document.getElementById('panel-' + id)?.remove();
   tabs.splice(idx, 1);
   if (activeTab?.id === id) activeTab = tabs[Math.min(idx, tabs.length - 1)] || null;
   if (activeTab) switchTab(activeTab.id);
   renderTabs();
   renderSidebar();
   persistOpenTabs();
 }

