async function runnerPanelScan() {
  const base = runnerBase();
  const line = $('runner-line');
  if (!base) { line.textContent = 'Живой хаб не найден — сначала запусти NPM-Hub.'; return; }
  const box = $('runner-scan');
  if (box) box.innerHTML = '<span class="note">сканирую…</span>';
  let r;
  try { r = await fetch(`${base}/api/runner`).then(x => x.json()); }
  catch (e) { r = { success: false, error: 'хаб не ответил по ' + base }; }
  PRUN = r;
  if (!r.success) {
    if (box) box.innerHTML = `<span class="danger">${esc(r.error || 'нет ответа')}</span>`;
    return;
  }
  line.innerHTML = `Хаб: <code>${esc(base)}</code> · ${esc(r.repo || '')} #${esc(r.runNumber || '')} · ${esc(r.os || '')}`
    + (r.tunnel ? ` · 🌐 <a href="${esc(r.tunnel)}" target="_blank" rel="noreferrer">туннель</a>` : '');
  const items = [];
  (r.apks || []).forEach(a => items.push({ name: a.name, path: a.path, size: a.size, isDir: false, kind: 'apk' }));
  (r.folders || []).forEach(f => items.push({ name: f.name, path: f.path, size: f.size, isDir: true, kind: 'folder' }));
  const save = $('pr-save');
  if (!items.length) {
    if (box) box.innerHTML = '<span class="note">Ничего не нашлось в ~/hub-work. Наполни вкладку «Файлы» в хабе, потом сканируй.</span>';
    if (save) save.disabled = true;
    return;
  }
  if (box) box.innerHTML = items.map(it => `<div class="item">
    <div class="ico">${it.kind === 'apk' ? '📦' : '📁'}</div>
    <div class="grow">
      <div class="name">${esc(it.name)}</div>
      <div class="meta">${prFmt(it.size)} · ${it.kind === 'apk' ? 'APK' : 'папка'}</div>
    </div>
    <select class="pr-dest" data-path="${esc(it.path)}" data-dir="${it.isDir ? '1' : ''}"
      style="padding:4px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--text);font-size:11px">
      <option value="phone"${it.kind === 'apk' ? ' selected' : ''}>на телефон</option>
      <option value="branch"${it.kind === 'folder' ? ' selected' : ''}>в ветку (tar.xz)</option>
      <option value="keep">оставить</option>
      <option value="skip">пропустить</option>
    </select>
  </div>`).join('');
  const onActs = !!(r.actions);
  const sp = $('pr-stop');
  if (sp) sp.disabled = !onActs;
  if (onActs === false && line) line.innerHTML += ' <span class="note">(локальный запуск — кнопки управления живут на Actions-раннере)</span>';
  if (save) save.disabled = false;
}
