input.command:
cd /home/runner/work/zen-panel/zen-panel/fork && ls ~/hub-work 2>/dev/null | head -5; echo "---"; node -e "
// Прогоняем ровно ту строку, что теперь в /api/runner, против настоящего WORK_DIR.
process.env.HUB_TOKEN='';
const path=require('path'), fs=require('fs'), os=require('os');
const WORK_DIR = process.env.HUB_WORK_DIR || path.join(os.homedir(),'hub-work');
const scanRunnerFiles = async () => {
  const apks = [], folders = [];
  const walk=(dir,depth)=>{ if(depth>6)return; let es; try{es=fs.readdirSync(dir,{withFileTypes:true});}catch{return;}
    for(const e of es){ if(!e||e.name.startsWith('.')||e.name==='node_modules'||e.name==='__pycache__')continue;
      const full=path.join(dir,e.name); try{ if(e.isDirectory()){ if(depth<3)walk(full,depth+1);} else if(/\.apk\$/i.test(e.name)){const st=fs.statSync(full); apks.push({name:e.name,path:full,size:st.size});} }catch{} } };
  walk(WORK_DIR,0);
  return { apks, folders, workDir: WORK_DIR };
};
scanRunnerFiles().then(r=>console.log('WORK_DIR =', r.workDir, '\napks =', r.apks.length));
"

