   // (full noVNC page). Local fallback: serve the bundled noVNC through the
   // hub's /ws/vnc proxy.
   cloudPhoneStatus(pfx).then(d => {
     const url = d.url
       ? d.url
       : cloudPhoneUrl() + '?autoconnect=1&path=ws/vnc&reconnect=1&reconnect_delay=3000';
