       <button class="btn btn-p" onclick="showNewTermModal();toggleDrawer()">+ Сессия</button>
     </div>
   </div>

   <!-- MAIN -->
   <div class="main">
     <div class="content">

       <!-- DASHBOARD -->
       <div class="page" id="p-dashboard">
         <div class="ph"><h1>Dashboard</h1><p>AI инструменты — выберите папку и нажмите Применить</p></div>

         <!-- Сайт хаба: показывается при каждом открытии хаба — копировать адрес
              или открыть панель в системном браузере устройства. -->
         <div id="site-card" class="card" style="margin-bottom:12px">
