             <button class="btn" onclick="copyHubSiteUrl()" title="Скопировать адрес сайта">📋 Скопировать</button>
           </div>
         </div>

         <div class="stats" id="stats"></div>
         <div class="grid" id="grid"></div>
         <div id="runner-card"></div>
       </div>

       <!-- TERMINAL -->
       <div class="term-page" id="p-terminal">
         <div class="term-topbar">
           <div class="tabs-row" id="tabs"></div>
           <div class="term-controls">
             <button class="tc-btn" onclick="killTerm()" ontouchend="event.preventDefault();killTerm()" oncontextmenu="event.preventDefault()" title="Стоп">⏹</button>
             <button class="tc-btn" onclick="sendEscape()" ontouchend="event.preventDefault();sendEscape()" oncontextmenu="event.preventDefault()" title="Escape">Esc</button>
             <button class="tc-btn" onclick="pasteClipboard()" ontouchend="event.preventDefault();pasteClipboard()" oncontextmenu="event.preventDefault()" title="Вставить">📋</button>
             <button class="tc-btn" onclick="copySelection()" ontouchend="event.preventDefault();copySelection()" oncontextmenu="event.preventDefault()" title="Копировать">⧉</button>
             <button class="tc-btn" onclick="restartTerm()" ontouchend="event.preventDefault();restartTerm()" oncontextmenu="event.preventDefault()" title="Перезапустить">⟲</button>
             <button class="tc-btn" onclick="zoomTerm(-1)" ontouchend="event.preventDefault();zoomTerm(-1)" oncontextmenu="event.preventDefault()">−</button>
             <span class="zoom-label" id="zoom-label">60%</span>
