           <button class="btn" onclick="gitFmShow()" title="Ручной git: создать репо / коммит / push этой папки">📝 git</button>
           <button class="btn" onclick="fmOpenScreen()" title="Открыть на экране (вкладка Экран)">🖥</button>
           <div style="position:relative;margin-left:auto">
             <button class="btn btn-p" onclick="toggleFmMenu(event)">▶</button>
             <div class="apply-menu" id="fm-apply-menu"></div>
           </div>
         </div>
         <div class="fm-list" id="fm-list"></div>
         <div class="fm-info" id="fm-info"></div>
         <div class="fm-transfer" id="fm-transfer" style="margin-top:8px;display:none;background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:8px;font-size:11px;color:var(--t3)">
           <div id="fm-transfer-name"></div>
           <div style="margin-top:4px;height:6px;border-radius:3px;background:var(--bdr);overflow:hidden"><div id="fm-transfer-bar" style="height:100%;width:0%;background:#58a6ff"></div></div>
           <div style="margin-top:4px"><span id="fm-transfer-progress"></span> · <span id="fm-transfer-speed"></span>/s · осталось <span id="fm-transfer-time"></span></div>
           <div style="margin-top:4px"><span id="fm-transfer-transferred"></span><span id="fm-transfer-total"></span></div>
         </div>
       </div>

 <!-- LINUX DESKTOP (VNC) — ОДИН ЭКРАН ДЛЯ ВСЕГО (RDP/VNC) -->
       <div class="page" id="p-linux" style="padding:0;flex-direction:column;height:100%">
         <!-- Одна тонкая строка: только управление экраном. Адрес, звук, починка —
              во вкладке «Настройки» (p-screen-settings). Экран — экран, не панель. -->
         <div class="linux-bar">
           <span id="linux-status" class="tag">…</span>
           <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨</button>
           <button class="btn btn-sm" id="linux-zoom-btn" onclick="linuxZoomToggle()" title="Заполнить / весь стол / 1:1">🔎</button>
           <button class="btn btn-sm" id="linux-perf-btn" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡</button>
           <button class="btn btn-sm" id="linux-mouse-btn" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱</button>
           <button class="btn btn-sm" onclick="linuxFullscreen()" title="На весь экран + поворот в ландшафт">⛶</button>
           <span id="linux-note"></span>
         </div>
         <style>
           /* ⛶ — экран на весь экран без потери noVNC-сессии.
              100dvh: на мобильных адресная строка Safari/Chrome иначе «съедает»
              часть высоты и картинка не заполняет экран. */
           #p-linux.linux-full{position:fixed!important;inset:0!important;height:100vh!important;height:100dvh!important;z-index:99999;background:#000}
           #p-linux.linux-full > .linux-bar, #p-linux.linux-full > #linux-more{display:none!important}
           /* «Просто рабочий стол»: на странице «Экран» не нужна шапка приложения —
              уйти можно нижним меню, а в полном экране есть ✕. */
           body.pg-linux .topbar{display:none}
           .linux-bar{display:flex;gap:6px;padding:6px 8px;background:var(--bg1);border-bottom:1px solid var(--bdr);flex-shrink:0;align-items:center;flex-wrap:nowrap;overflow:hidden}
           .linux-bar #linux-note{font-size:10px;color:var(--t3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
           #linux-more{display:flex;gap:6px;padding:6px 8px;background:var(--bg2);border-bottom:1px solid var(--bdr);flex-shrink:0;flex-wrap:wrap;align-items:center}
           #linux-more[hidden]{display:none}
           #linux-read{display:flex;gap:6px;align-items:center;flex-wrap:wrap;width:100%}
           #p-linux.linux-full #linux-stack{flex:1 1 auto;height:100%}
           /* В полном экране тулбары скрыты, поэтому клавиатура, масштаб и
              выход живут здесь — иначе за клавиатурой приходилось выходить из
              полноэкранного режима (на это и жаловались). */
           .linux-fsctl{display:none}
           #p-linux.linux-full .linux-fsctl{display:flex;gap:8px;position:absolute;top:10px;right:10px;z-index:100000}
           #p-linux.linux-full .linux-fsctl button{
             background:rgba(13,17,23,.8);color:#e6edf3;border:1px solid rgba(240,246,252,.25);
             border-radius:50%;width:40px;height:40px;font-size:16px;line-height:1}
           @media (max-width:560px){ .linux-hint{display:none!important} }
           /* ── Виртуальная мышь ──────────────────────────────────────────────
              Палец по картинке — плохой курсор: он закрывает то место, куда
              целишься, промах по мелкой кнопке уходит в пустоту, а скролл
              вообще некуда деть. Поэтому мышь отдельная: слева сенсор, справа
              ЛКМ/ПКМ, в центре колесо стрелками. */
           #linux-mouse{position:absolute;left:0;right:0;bottom:0;z-index:99990;display:flex;gap:8px;align-items:stretch;
             padding:8px;background:linear-gradient(180deg,rgba(13,17,23,.78),rgba(13,17,23,.95));
             border-top:1px solid rgba(240,246,252,.18);backdrop-filter:blur(6px);
             touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
           #linux-mouse[hidden]{display:none}
           .lm-pad{flex:1 1 auto;min-width:96px;min-height:104px;border-radius:12px;border:1px dashed rgba(240,246,252,.28);
             background:rgba(255,255,255,.05);display:flex;align-items:center;justify-content:center;color:var(--t3);
             font-size:10px;line-height:1.35;text-align:center;touch-action:none;position:relative;overflow:hidden}
           .lm-pad.active{background:rgba(88,166,255,.16);border-color:var(--acc)}
           .lm-pad-hint{pointer-events:none;padding:0 8px}
           .lm-buttons{display:flex;flex-direction:column;gap:6px;width:74px;flex:0 0 auto}
           .lm-btn{flex:1;border-radius:10px;border:1px solid rgba(240,246,252,.22);background:rgba(255,255,255,.07);
             color:#e6edf3;font-size:12px;font-weight:700;touch-action:none}
           .lm-btn.on,.lm-btn:active{background:var(--acc);color:#0d1117;border-color:var(--acc)}
           .lm-wheel{display:flex;flex-direction:column;gap:4px;width:88px;align-items:center;justify-content:center;flex:0 0 auto}
           .lm-wheel-mid{display:flex;gap:4px}
           .lm-arr{width:40px;height:30px;border-radius:8px;border:1px solid rgba(240,246,252,.22);
             background:rgba(255,255,255,.07);color:#e6edf3;font-size:13px;line-height:1;touch-action:none}
           .lm-arr.on,.lm-arr:active{background:var(--acc);color:#0d1117;border-color:var(--acc)}
           .lm-close{position:absolute;top:2px;right:4px;width:24px;height:24px;border-radius:50%;
             border:1px solid rgba(240,246,252,.25);background:rgba(13,17,23,.75);color:#e6edf3;font-size:11px;line-height:1;padding:0}
           #p-linux.linux-full #linux-mouse{padding-bottom:max(8px,env(safe-area-inset-bottom))}
         </style>
         <div id="browser-agent-hint" style="display:none;padding:8px 10px;background:rgba(88,166,255,.14);border-bottom:1px solid var(--bdr);font-size:12px;color:var(--acc);align-items:center;gap:8px;flex-wrap:wrap;flex-shrink:0">
           <span>🔗 Агент прислал ссылку:</span><a id="browser-agent-url" href="#" target="_blank" style="color:var(--acc);word-break:break-all"></a>
           <button class="btn btn-p btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-agent-url').textContent)">🖥 Открыть на экране</button>
           <button class="btn btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-agent-url').textContent, true)">📱 вертикально</button>
           <span style="margin-left:auto;cursor:pointer" onclick="document.getElementById('browser-agent-hint').style.display='none'">✕</span>
         </div>
         <div id="linux-stack" style="flex:1;position:relative;background:#000">
           <div class="linux-fsctl">
             <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨</button>
             <button class="btn btn-sm" onclick="linuxZoomToggle()" title="Заполнить / 1:1">🔍</button>
             <button class="btn btn-sm" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡</button>
             <button class="btn btn-sm" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱</button>
             <button class="btn btn-sm" onclick="linuxFullscreen()" title="Выйти из полного экрана">✕</button>
           </div>
           <iframe id="linux-frame" style="width:100%;height:100%;border:none;display:none" allow="fullscreen; clipboard-read; clipboard-write" allowfullscreen></iframe>
           <!-- Виртуальная мышь: сенсор (палец двигает курсор), две кнопки и
                колесо стрелками. Работает поверх картинки экрана и не мешает
                прямым касаниям по ней. -->
           <div id="linux-mouse" hidden>
             <div class="lm-pad" id="lm-pad">
               <span class="lm-pad-hint">СЕНСОР · тяни — курсор, тап — клик, два тапа — двойной</span>
             </div>
             <div class="lm-buttons">
               <button class="lm-btn" id="lm-left" onpointerdown="vMouseDown(1)" onpointerup="vMouseUp(1)" onpointercancel="vMouseUp(1)" onpointerleave="vMouseUp(1)">ЛКМ</button>
               <button class="lm-btn" id="lm-right" onpointerdown="vMouseDown(4)" onpointerup="vMouseUp(4)" onpointercancel="vMouseUp(4)" onpointerleave="vMouseUp(4)">ПКМ</button>
             </div>
             <div class="lm-wheel">
               <button class="lm-arr" data-dir="up" onpointerdown="vMouseWheelStart('up')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">▲</button>
               <div class="lm-wheel-mid">
                 <button class="lm-arr" data-dir="left" onpointerdown="vMouseWheelStart('left')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">◀</button>
                 <button class="lm-arr" data-dir="right" onpointerdown="vMouseWheelStart('right')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">▶</button>
               </div>
               <button class="lm-arr" data-dir="down" onpointerdown="vMouseWheelStart('down')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">▼</button>
             </div>
             <button class="lm-close" onclick="linuxMouseToggle()" title="Скрыть мышь">✕</button>
           </div>
           <div id="linux-placeholder" style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;color:var(--t3);text-align:center;padding:20px">
             <div style="font-size:48px;margin-bottom:16px">🖥</div>
             <div style="font-size:16px;font-weight:600;margin-bottom:8px;color:var(--t2)">Один экран</div>
             <div style="font-size:13px;max-width:320px;line-height:1.5">Всё — браузер, терминал, файлы — на одном рабочем столе Linux (openbox).<br>Вкладка <b>🎛 Настройки</b> откроет Chromium прямо здесь, звук уже 80%.<br><span style="color:var(--t3)">Телефон тоже здесь: «📱 вертикально» в настройках открывает вертикальный ютуб.</span></div>
             <button class="btn btn-p btn-sm" onclick="linuxRepair()" style="margin-top:14px">🔧 Починить экран</button>
             <div id="pulse-devices" style="margin-top:12px;font-size:11px;color:var(--t3);text-align:left"></div>
           </div>
         </div>
         <!-- cloud phone теперь не нужен отдельно — всё на одном DISPLAY -->
         <iframe id="cp-frame" style="display:none" allowfullscreen></iframe>
       </div>

       <!-- SCREEN SETTINGS — все настройки экрана в одном месте (раньше жили
            под «⋯» вкладки «Экран»). Экран — это экран, настройки — здесь. -->
       <div class="page" id="p-screen-settings">
         <div class="ph"><h1>🎛 Настройки экрана</h1><p>Вид, браузер, звук, AVD и голос на удалённом столе</p></div>

         <div id="screen-settings-body">
           <div class="card" style="margin-bottom:10px">
             <div class="card-h">
               <div class="card-ico" style="background:rgba(88,166,255,.12);color:var(--acc)">👁</div>
               <div><div class="card-n">Вид экрана</div><div class="card-v">Кнопки действуют на вкладке «Экран»</div></div>
             </div>
             <div style="display:flex;gap:6px;flex-wrap:wrap">
               <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨ Клавиатура</button>
               <button class="btn btn-sm" onclick="linuxZoomToggle()" title="Заполнить / весь стол / 1:1">🔎 Зум</button>
               <button class="btn btn-sm" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡ Плавность</button>
               <button class="btn btn-sm" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱 Мышь</button>
               <button class="btn btn-sm" onclick="linuxFullscreen()" title="На весь экран + поворот в ландшафт">⛶ Полный экран</button>
               <button class="btn btn-p btn-sm" onclick="showPage('linux')" title="Открыть экран">🖥 Открыть экран</button>
             </div>
           </div>

           <div id="linux-more">
             <input type="text" id="browser-url" placeholder="https://... — откроется на экране" value="https://www.youtube.com" style="flex:1;min-width:140px;padding:7px 10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:12px;outline:none" onkeydown="if(event.key==='Enter')linuxRunBrowser(this.value)">
             <button class="btn btn-p btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-url').value)" title="Открыть Chromium на экране (DISPLAY=:99)">Go · 🖥</button>
             <button class="btn btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-url').value, true)" title="Вертикально (Shorts) — окно под экран телефона">📱 вертикально</button>
             <span id="pulse-status" class="tag" role="button" tabindex="0" onclick="event.stopPropagation();remoteAudioToggle()" onkeydown="if(event.key==='Enter'||event.key===' ')remoteAudioToggle()" title="Включить звук видео с удалённого экрана" style="font-size:10px;cursor:pointer">🔊</span>
             <input type="range" id="pulse-vol" min="0" max="100" value="80" style="width:80px" oninput="pulseSetVol(this.value)">
             <span id="pulse-vol-label" style="font-size:11px;font-family:monospace;min-width:36px;text-align:right">80%</span>
             <button class="btn btn-sm" onclick="pulseToggleMute()" title="Мьют">🔇</button>
             <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--t2)" title="Сохраняется между перезапусками хаба"><span>AVD</span><input id="emulator-default" type="text" placeholder="pixel_7_api34" style="width:110px;padding:4px 6px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);font-size:11px" onkeydown="if(event.key==='Enter')saveEmulatorDefault()"></label>
             <button class="btn btn-sm" onclick="saveEmulatorDefault()" title="Сохранить AVD по умолчанию">✓ AVD</button>
             <button class="btn btn-sm" onclick="linuxRepair()" title="Пересобрать экран на этом раннере">🔧 починить</button>
             <!-- Читалка (TTS/OCR): жила во вкладке Chrome, а та дублировала
                  «Экран» (два браузера на одном телефоне) — переехала в настройки. -->
             <div id="linux-read">
               <span style="color:var(--pur);font-weight:700">🔊 TTS/OCR:</span>
               <button class="btn btn-p btn-sm" id="tts-play-btn" onclick="ttsToggle()">▶ Читать</button>
               <button class="btn btn-sm" onclick="ttsStop()">⏹ Стоп</button>
               <button class="btn btn-sm" onclick="ttsPause()">⏸ Пауза</button>
               <select id="tts-voice" style="padding:4px 6px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);font-size:11px;max-width:120px"></select>
               <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--t2)"><input type="range" id="tts-rate" min="0.5" max="2" step="0.1" value="1" style="width:60px" oninput="ttsSetRate(this.value)"> <span id="tts-rate-label">1×</span></label>
               <label style="display:flex;align-items:center;gap:3px;font-size:11px;color:var(--t2)"><input type="checkbox" id="tts-autoscroll" checked> Авто-скролл</label>
               <label style="display:flex;align-items:center;gap:3px;font-size:11px;color:var(--t2)"><input type="checkbox" id="tts-bg" checked> В фоне</label>
               <button class="btn btn-sm" onclick="ocrCapture()" title="Распознать текст с экрана (OCR)">👁️ OCR</button>
               <span id="tts-status" style="font-size:10px;color:var(--t3);margin-left:auto">готов</span>
             </div>
           </div>
         </div>
         <style>
           #p-screen-settings #linux-more{display:flex;gap:6px;flex-wrap:wrap;align-items:center;background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:12px;margin-bottom:10px}
           #p-screen-settings #linux-more[hidden]{display:none}
           #p-screen-settings #linux-read{display:flex;gap:6px;align-items:center;flex-wrap:wrap;width:100%;border-top:1px solid var(--bdr);padding-top:10px;margin-top:4px}
           #p-screen-settings .btn:active{opacity:.85}
         </style>
